-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-TLT-01', 'C6-B20-M1', 'Cho rằng cứ viết hai tỉ số bằng dấu "=" là được tỉ lệ thức, không kiểm tra hai tỉ số có bằng nhau không. Ví dụ: Cho rằng 2/3 và 4/5 lập thành tỉ lệ thức', 'VBH-TLT-01'),
  ('E-TLT-02', 'C6-B20-M1', 'Nhầm ngoại tỉ (a và d) với trung tỉ (b và c) của tỉ lệ thức a/b = c/d. Ví dụ: Trong 2/3 = 4/6 cho rằng 3 và 4 là ngoại tỉ', 'VBH-TLT-02'),
  ('E-TLT-03', 'C6-B20-M2', 'Áp dụng tính chất ad = bc sai: nhân tử với tử, mẫu với mẫu, hoặc chia sai khi tìm số hạng chưa biết. Ví dụ: x/4 = 3/6 nên x = 4 · 6 : 3 = 8', 'VBH-TLT-03'),
  ('E-TLT-04', 'C6-B20-M2', 'Từ đẳng thức ad = bc lập tỉ lệ thức bằng cách đổi chỗ tuỳ ý, không giữ hai thừa số của một tích ở hai vị trí ngoại tỉ (hoặc trung tỉ). Ví dụ: Từ 2 · 6 = 3 · 4 lập 2/3 = 6/4', 'VBH-TLT-04'),
  ('E-DTS-01', 'C6-B21-M1', 'Viết sai "x, y, z tỉ lệ với a, b, c" thành a/x = b/y = c/z, x/b = y/a hay ax = by. Ví dụ: x, y tỉ lệ với 2 và 3 viết thành 2x = 3y', 'VBH-DTS-01'),
  ('E-DTS-02', 'C6-B21-M1B', 'Dùng tính chất dãy tỉ số bằng nhau sai: nhân tử với nhau, hoặc tử trừ mà mẫu lại cộng. Ví dụ: x/2 = y/3 = (x − y)/(2 + 3)', 'VBH-DTS-02'),
  ('E-DTS-03', 'C6-B21-M1B', 'Khi đề cho tổng 2x + y (có hệ số) vẫn cộng thẳng các mẫu, không biến đổi x/2 thành 2x/4 trước. Ví dụ: x/2 = y/3 và 2x + y = 14 nên (2x + y)/(2 + 3) = 14/5', 'VBH-DTS-03'),
  ('E-DTS-04', 'C6-B21-M2', 'Lập dãy tỉ số từ bài toán có lời văn nhưng gán đại lượng với số không đúng thứ tự, hoặc không dùng hết dữ kiện tổng. Ví dụ: Ba lớp 7A, 7B, 7C trồng cây tỉ lệ với 3; 4; 5 nhưng cho 7A ứng với 5', 'VBH-DTS-04'),
  ('E-TLTH-01', 'C6-B22-M1', 'Cho rằng hai đại lượng cùng tăng (hoặc cùng giảm) thì tỉ lệ thuận, không kiểm tra y = kx. Ví dụ: y = x + 3 nên y tỉ lệ thuận với x', 'VBH-TLTH-01'),
  ('E-TLTH-02', 'C6-B22-M1', 'Cho rằng y tỉ lệ thuận với x theo hệ số k thì x tỉ lệ thuận với y cũng theo hệ số k. Ví dụ: y = 3x nên x tỉ lệ thuận với y theo hệ số 3', 'VBH-TLTH-02'),
  ('E-TLTH-03', 'C6-B22-M2', 'Dùng tích hai giá trị tương ứng không đổi (tính chất tỉ lệ nghịch) cho hai đại lượng tỉ lệ thuận. Ví dụ: x = 2 thì y = 6; x = 3 thì cho y = 2·6 : 3 = 4', 'VBH-TLTH-03'),
  ('E-TLTH-04', 'C6-B22-M3', 'Giải bài toán tỉ lệ thuận nhưng đặt các giá trị không tương ứng vào tỉ lệ thức nên kết quả ngược. Ví dụ: 5 m dây nặng 120 g thì 8 m dây nặng 5 · 120 : 8 = 75 g', 'VBH-TLTH-04'),
  ('E-TLN-01', 'C6-B23-M1', 'Cho rằng hai đại lượng mà một tăng thì một giảm là tỉ lệ nghịch, không kiểm tra tích xy không đổi. Ví dụ: y = 10 − x nên y tỉ lệ nghịch với x', 'VBH-TLN-01'),
  ('E-TLN-02', 'C6-B23-M2', 'Áp dụng x1/x2 = y1/y2 (tính chất tỉ lệ thuận) cho hai đại lượng tỉ lệ nghịch. Ví dụ: x tăng gấp đôi thì cho y cũng tăng gấp đôi dù y tỉ lệ nghịch với x', 'VBH-TLN-02'),
  ('E-TLN-03', 'C6-B23-M3', 'Không xác định đúng hai đại lượng trong bài toán thực tế là tỉ lệ thuận hay tỉ lệ nghịch (số công nhân – thời gian, vận tốc – thời gian). Ví dụ: 4 người làm xong trong 6 ngày, 8 người làm xong trong 12 ngày', 'VBH-TLN-03')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

