  ('C6-B20-M1-Q06', 'C6-B20-M1', 3, 'Từ tỉ lệ thức 4/7 = 12/21, phát biểu nào ĐÚNG?', 'A', 90, null),
  ('C6-B20-M1-Q07', 'C6-B20-M1', 4, 'Lớp 7A có 15 nam, 20 nữ; lớp 7B có 18 nam, 24 nữ. Tỉ số số nam và số nữ của hai lớp có lập thành tỉ lệ thức không?', 'A', 120, null),
  ('C6-B20-M1-Q08', 'C6-B20-M1', 4, 'Một công thức pha nước chanh dùng 2 thìa đường cho 3 cốc nước. Bạn Lan dùng 5 thìa đường cho 7 cốc nước. Phát biểu nào ĐÚNG?', 'A', 120, null),
  ('C6-B20-M2-Q01', 'C6-B20-M2', 1, 'Nếu a/b = c/d thì:', 'A', 45, null),
