  ('C6-B21-M1-Q04', 'C6-B21-M1', 2, 'Số học sinh của ba tổ tỉ lệ với 3; 4; 5. Gọi số học sinh ba tổ là a, b, c. Cách viết ĐÚNG là:', 'A', 60, null),
