  ('C6-B21-M1B-Q08', 'C6-B21-M1B', 4, 'Cho a/b = c/d (các mẫu khác 0, b ≠ d). Bạn Huy viết a/b = (a − c)/(b + d). Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C6-B21-M2-Q01', 'C6-B21-M2', 1, 'Chia số 30 thành hai phần tỉ lệ với 2 và 3. Hai phần đó là:', 'A', 45, null),
  ('C6-B21-M2-Q02', 'C6-B21-M2', 1, 'Hai lớp 7A, 7B thu được 70 kg giấy vụn, số giấy tỉ lệ với 3 và 4. Lớp 7A thu được:', 'A', 45, null),
  ('C6-B21-M2-Q03', 'C6-B21-M2', 2, 'Ba lớp 7A, 7B, 7C trồng 60 cây, số cây tỉ lệ với 3; 4; 5. Số cây lớp 7C trồng là:', 'A', 60, null),
  ('C6-B21-M2-Q04', 'C6-B21-M2', 2, 'Tỉ số tuổi của anh và em là 5 : 3, anh hơn em 6 tuổi. Tuổi của anh là:', 'A', 60, null),
  ('C6-B21-M2-Q05', 'C6-B21-M2', 3, 'Ba cạnh của một tam giác tỉ lệ với 3; 4; 5 và chu vi là 48 cm. Cạnh lớn nhất dài:', 'A', 90, null),
  ('C6-B21-M2-Q06', 'C6-B21-M2', 3, 'Số học sinh giỏi, khá, đạt của khối 7 tỉ lệ với 2; 5; 3. Số học sinh khá nhiều hơn số học sinh giỏi là 45 em. Số học sinh đạt là:', 'A', 90, null),
