  ('C6-B22-M2-Q04', 'C6-B22-M2', 2, 'Hai đại lượng x, y tỉ lệ thuận. Khẳng định nào ĐÚNG?', 'A', 60, null),
  ('C6-B22-M2-Q05', 'C6-B22-M2', 3, 'x và y tỉ lệ thuận; x = −2 thì y = 8. Biểu diễn y theo x:', 'A', 90, null),
