  ('C6-B22-M3-Q04', 'C6-B22-M3', 2, 'Hai thanh sắt cùng loại có khối lượng 12 kg và 18 kg. Thanh thứ nhất dài 2 m. Thanh thứ hai dài:', 'A', 60, null),
