  ('C6-B22-M3-Q06', 'C6-B22-M3', 3, 'Chia 150 quyển vở cho ba lớp tỉ lệ thuận với số học sinh là 30; 35; 35. Lớp có 30 học sinh nhận:', 'A', 90, null),
  ('C6-B22-M3-Q07', 'C6-B22-M3', 4, 'Một bản đồ tỉ lệ 1 : 500 000. Khoảng cách trên bản đồ là 4 cm thì khoảng cách thực tế là:', 'A', 120, null),
