  ('C6-B23-M3-Q02', 'C6-B23-M3', 1, 'Một ô tô đi từ A đến B với vận tốc 40 km/h hết 3 giờ. Nếu đi với vận tốc 60 km/h thì hết:', 'A', 45, null),
