insert into error_hints (error_code, tier, hint_text) values
  ('E-TLT-01', 1, 'Hai tỉ số này có bằng nhau không? Em thử rút gọn từng tỉ số.'),
  ('E-TLT-01', 2, 'Tỉ lệ thức là đẳng thức của hai tỉ số BẰNG NHAU: a/b = c/d. Viết dấu "=" giữa hai tỉ số khác nhau thì không phải tỉ lệ thức.'),
  ('E-TLT-01', 3, 'Ví dụ: 2/3 và 8/12 đều rút gọn được về 2/3 nên lập thành tỉ lệ thức; 2/3 và 4/5 thì không vì 2 · 5 ≠ 3 · 4.'),
  ('E-TLT-02', 1, 'Trong a/b = c/d, số nào đứng ở hai đầu, số nào đứng ở giữa?'),
  ('E-TLT-02', 2, 'Viết tỉ lệ thức dạng a : b = c : d. Hai số ở ngoài cùng (a và d) là ngoại tỉ; hai số ở giữa (b và c) là trung tỉ.'),
  ('E-TLT-02', 3, 'Ví dụ: 3/5 = 6/10 viết thành 3 : 5 = 6 : 10. Ngoại tỉ là 3 và 10; trung tỉ là 5 và 6.'),
  ('E-TLT-03', 1, 'Em đã nhân đúng cặp số nào với nhau?'),
  ('E-TLT-03', 2, 'Trong tỉ lệ thức, tích hai ngoại tỉ bằng tích hai trung tỉ: a/b = c/d ⇒ ad = bc (nhân "chéo"). Muốn tìm một ngoại tỉ, lấy tích hai trung tỉ chia cho ngoại tỉ đã biết.'),
  ('E-TLT-03', 3, 'Ví dụ: x/4 = 3/6 ⇒ 6x = 4 · 3 = 12 ⇒ x = 2. Kiểm tra: 2/4 = 3/6 = 1/2.'),
  ('E-TLT-04', 1, 'Trong tỉ lệ thức em lập, hai số nào là ngoại tỉ? Tích của chúng có đúng là một vế của đẳng thức không?'),
  ('E-TLT-04', 2, 'Từ ad = bc: hai thừa số của một tích phải cùng làm ngoại tỉ, hai thừa số của tích kia làm trung tỉ. Ta lập được 4 tỉ lệ thức: a/b = c/d; a/c = b/d; d/b = c/a; d/c = b/a.'),
  ('E-TLT-04', 3, 'Ví dụ: 2 · 6 = 3 · 4 ⇒ 2/3 = 4/6 (ngoại tỉ 2 và 6). Viết 2/3 = 6/4 là sai vì 2 · 4 ≠ 3 · 6.'),
  ('E-DTS-01', 1, 'Trong "x tỉ lệ với 2", số 2 nằm ở tử hay ở mẫu của tỉ số có x?'),
  ('E-DTS-01', 2, '"x, y, z tỉ lệ với a, b, c" nghĩa là x/a = y/b = z/c, cũng viết là x : y : z = a : b : c. Đại lượng ở tử, số cho trước ở mẫu, giữ đúng thứ tự.'),
  ('E-DTS-01', 3, 'Ví dụ: x, y tỉ lệ với 2 và 3 ⇒ x/2 = y/3 (không phải 2x = 3y; nếu 2x = 3y thì x/3 = y/2).'),
  ('E-DTS-02', 1, 'Ở tử em cộng hay trừ? Còn ở mẫu thì sao?'),
  ('E-DTS-02', 2, 'a/b = c/d = (a + c)/(b + d) = (a − c)/(b − d) (các mẫu khác 0). Tử làm phép tính nào thì mẫu làm đúng phép tính đó. Không nhân các tử với nhau.'),
  ('E-DTS-02', 3, 'Ví dụ: x/5 = y/3 và x − y = 8 ⇒ x/5 = y/3 = (x − y)/(5 − 3) = 8/2 = 4 ⇒ x = 20; y = 12.'),
  ('E-DTS-03', 1, 'Trong tổng đề cho, x có hệ số bao nhiêu? Tỉ số của em đã có 2x ở tử chưa?'),
  ('E-DTS-03', 2, 'Muốn dùng tổng 2x + y thì phải biến đổi để tử có 2x: nhân cả tử và mẫu của x/2 với 2 được 2x/4. Sau đó mới cộng tử với tử, mẫu với mẫu.'),
  ('E-DTS-03', 3, 'Ví dụ: x/2 = y/3 ⇒ 2x/4 = y/3 = (2x + y)/(4 + 3) = 14/7 = 2 ⇒ x = 4; y = 6.'),
  ('E-DTS-04', 1, 'Đại lượng nào ứng với số nào? Em đã dùng tổng (hay hiệu) đề cho chưa?'),
  ('E-DTS-04', 2, 'Gọi tên các đại lượng theo đúng thứ tự đề bài, viết dãy tỉ số giữ thứ tự đó, rồi dùng dữ kiện tổng hoặc hiệu để tìm giá trị chung của dãy tỉ số.'),
  ('E-DTS-04', 3, 'Ví dụ: 7A, 7B, 7C trồng 60 cây tỉ lệ với 3; 4; 5 ⇒ a/3 = b/4 = c/5 = 60/12 = 5 ⇒ 7C trồng c = 25 cây.'),
  ('E-TLTH-01', 1, 'Em thử tính y/x với vài cặp giá trị. Thương có luôn bằng một số cố định không?'),
  ('E-TLTH-01', 2, 'y tỉ lệ thuận với x khi y = kx (k ≠ 0), tức là y/x luôn bằng k. "Cùng tăng" chưa đủ: y = x + 3 cùng tăng nhưng y/x thay đổi.'),
  ('E-TLTH-01', 3, 'Ví dụ: y = x + 3: x = 1 thì y/x = 4; x = 3 thì y/x = 2. Thương thay đổi nên không tỉ lệ thuận.'),
  ('E-TLTH-02', 1, 'Từ y = kx, em hãy rút x theo y.'),
  ('E-TLTH-02', 2, 'Nếu y tỉ lệ thuận với x theo hệ số k thì x = (1/k)y, tức x tỉ lệ thuận với y theo hệ số 1/k.'),
  ('E-TLTH-02', 3, 'Ví dụ: y = 3x ⇒ x = (1/3)y. x tỉ lệ thuận với y theo hệ số 1/3, không phải 3.'),
  ('E-TLTH-03', 1, 'Với hai đại lượng tỉ lệ thuận, cái gì không đổi: tích hay thương?'),
  ('E-TLTH-03', 2, 'Tỉ lệ thuận: y1/x1 = y2/x2 = k (thương không đổi) và x1/x2 = y1/y2. Tích không đổi là tính chất của tỉ lệ nghịch.'),
  ('E-TLTH-03', 3, 'Ví dụ: x = 2 thì y = 6 ⇒ k = 3. Khi x = 3 thì y = 3 · 3 = 9 (không phải 4).'),
  ('E-TLTH-04', 1, 'Các giá trị tương ứng (5 m – 120 g; 8 m – ? g) em đã xếp cùng hàng chưa?'),
  ('E-TLTH-04', 2, 'Lập bảng hai hàng: hàng trên một đại lượng, hàng dưới đại lượng kia, các giá trị tương ứng cùng cột. Tỉ lệ thuận: các thương (dưới/trên) bằng nhau.'),
  ('E-TLTH-04', 3, 'Ví dụ: 120/5 = x/8 ⇒ x = 120 · 8 : 5 = 192 g. Kiểm tra: dây dài hơn thì nặng hơn.'),
  ('E-TLN-01', 1, 'Em thử tính tích xy với vài cặp giá trị. Tích có luôn bằng một số cố định không?'),
  ('E-TLN-01', 2, 'y tỉ lệ nghịch với x khi xy = a (a ≠ 0). "Một tăng một giảm" chưa đủ: y = 10 − x thì x tăng y giảm nhưng xy thay đổi.'),
  ('E-TLN-01', 3, 'Ví dụ: y = 10 − x: x = 1 thì xy = 9; x = 5 thì xy = 25. Tích thay đổi nên không tỉ lệ nghịch.'),
  ('E-TLN-02', 1, 'Với tỉ lệ nghịch, khi x gấp đôi thì y gấp đôi hay giảm một nửa?'),
  ('E-TLN-02', 2, 'Tỉ lệ nghịch: x1y1 = x2y2 = a, nên x1/x2 = y2/y1 (tỉ số "đảo ngược"). Không dùng x1/x2 = y1/y2.'),
  ('E-TLN-02', 3, 'Ví dụ: x = 2 thì y = 6 ⇒ a = 12. Khi x = 3 thì y = 12 : 3 = 4.'),
  ('E-TLN-03', 1, 'Nếu đại lượng này tăng gấp đôi thì đại lượng kia gấp đôi hay giảm một nửa?'),
  ('E-TLN-03', 2, 'Cùng một công việc: nhiều người hơn thì ít ngày hơn (tỉ lệ nghịch). Cùng một quãng đường: đi nhanh hơn thì ít thời gian hơn (tỉ lệ nghịch). Cùng một loại hàng: mua nhiều hơn thì trả nhiều tiền hơn (tỉ lệ thuận).'),
  ('E-TLN-03', 3, 'Ví dụ: 4 người làm 6 ngày ⇒ 4 · 6 = 24 "ngày công". 8 người làm 24 : 8 = 3 ngày, không phải 12 ngày.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-TLT-01', 'Nhiều bạn cứ thấy hai tỉ số viết cạnh nhau là gọi tỉ lệ thức. Điều quan trọng nhất lại hay bị bỏ qua: hai tỉ số đó phải bằng nhau.', 'Tỉ lệ thức là đẳng thức của hai tỉ số bằng nhau: a/b = c/d. Muốn kiểm tra, rút gọn hai tỉ số hoặc so sánh a · d với b · c.', '[{"de":"2/3 và 4/5 có lập thành tỉ lệ thức không?","giai":"Cách nghĩ sai: viết được 2/3 = 4/5 nên là tỉ lệ thức. Cách đúng: 2 · 5 = 10 còn 3 · 4 = 12, hai tỉ số không bằng nhau nên không lập thành tỉ lệ thức."},{"de":"1,2 : 3,6 và 2 : 6 có lập thành tỉ lệ thức không?","giai":"1,2 : 3,6 = 1/3 và 2 : 6 = 1/3. Hai tỉ số bằng nhau nên lập thành tỉ lệ thức 1,2 : 3,6 = 2 : 6."}]'::jsonb, '[{"de":"3/4 và 9/12 có lập thành tỉ lệ thức không?","dapAn":"Có","giaiThich":"9/12 rút gọn được 3/4."},{"de":"5/6 và 6/7 có lập thành tỉ lệ thức không?","dapAn":"Không","giaiThich":"5 · 7 = 35 khác 6 · 6 = 36."}]'::jsonb),
  ('VBH-TLT-02', 'Ngoại tỉ và trung tỉ chỉ là tên gọi theo vị trí. Viết tỉ lệ thức theo dạng a : b = c : d là nhìn ra ngay.', 'Trong a : b = c : d (hay a/b = c/d): a và d đứng ở hai đầu là ngoại tỉ; b và c đứng ở giữa là trung tỉ.', '[{"de":"Tìm ngoại tỉ của 2/3 = 4/6.","giai":"Cách nghĩ sai: 3 và 4 là ngoại tỉ vì \"ở ngoài phân số\". Cách đúng: viết 2 : 3 = 4 : 6; hai số ở hai đầu là 2 và 6, đó là ngoại tỉ. Trung tỉ là 3 và 4."},{"de":"Tìm trung tỉ của 5/8 = 10/16.","giai":"Viết 5 : 8 = 10 : 16. Trung tỉ là 8 và 10."}]'::jsonb, '[{"de":"Ngoại tỉ của 7/2 = 14/4 là?","dapAn":"7 và 4","giaiThich":"Hai số ở hai đầu của 7 : 2 = 14 : 4."},{"de":"Trung tỉ của 1/3 = 4/12 là?","dapAn":"3 và 4","giaiThich":"Hai số ở giữa của 1 : 3 = 4 : 12."}]'::jsonb),
  ('VBH-TLT-03', 'Khi tìm x trong tỉ lệ thức, lỗi hay gặp nhất là nhân nhầm cặp số. Quy tắc chỉ có một: tích ngoại tỉ bằng tích trung tỉ.', 'a/b = c/d ⇒ a · d = b · c. Muốn tìm một ngoại tỉ: lấy tích hai trung tỉ chia cho ngoại tỉ còn lại. Muốn tìm một trung tỉ: lấy tích hai ngoại tỉ chia cho trung tỉ còn lại.', '[{"de":"Tìm x biết x/4 = 3/6.","giai":"Cách nghĩ sai: x = 4 · 6 : 3 = 8. Cách đúng: x và 6 là ngoại tỉ, 4 và 3 là trung tỉ, nên 6x = 4 · 3 = 12, x = 2. Kiểm tra: 2/4 = 3/6 = 1/2."},{"de":"Tìm x biết 5/x = 15/12.","giai":"Ngoại tỉ 5 và 12, trung tỉ x và 15: 15x = 5 · 12 = 60 ⇒ x = 4."}]'::jsonb, '[{"de":"Tìm x biết x/5 = 6/10.","dapAn":"x = 3","giaiThich":"10x = 5 · 6 = 30."},{"de":"Tìm x biết 2/7 = x/21.","dapAn":"x = 6","giaiThich":"7x = 2 · 21 = 42."}]'::jsonb),
  ('VBH-TLT-04', 'Từ một đẳng thức tích ad = bc ta lập được đúng bốn tỉ lệ thức. Đổi chỗ tuỳ ý là dễ ra tỉ lệ thức sai.', 'Nếu ad = bc (a, b, c, d khác 0) thì a/b = c/d; a/c = b/d; d/b = c/a; d/c = b/a. Mẹo: hai thừa số của cùng một tích phải đứng ở hai đầu (ngoại tỉ) hoặc cùng đứng ở giữa (trung tỉ).', '[{"de":"Từ 2 · 6 = 3 · 4 lập một tỉ lệ thức.","giai":"Cách nghĩ sai: 2/3 = 6/4. Kiểm tra: 2 · 4 = 8 khác 3 · 6 = 18 nên sai. Cách đúng: 2 và 6 làm ngoại tỉ, 3 và 4 làm trung tỉ: 2/3 = 4/6."},{"de":"Lập đủ bốn tỉ lệ thức từ 5 · 8 = 4 · 10.","giai":"5/4 = 10/8; 5/10 = 4/8; 8/4 = 10/5; 8/10 = 4/5."}]'::jsonb, '[{"de":"Từ 3 · 10 = 5 · 6, tỉ lệ thức 3/5 = 6/10 đúng hay sai?","dapAn":"Đúng","giaiThich":"3 và 10 là ngoại tỉ, 5 và 6 là trung tỉ."},{"de":"Từ 3 · 10 = 5 · 6, tỉ lệ thức 3/6 = 10/5 đúng hay sai?","dapAn":"Sai","giaiThich":"3 · 5 = 15 khác 6 · 10 = 60."}]'::jsonb),
  ('VBH-DTS-01', '"Tỉ lệ với" là cách nói rất hay gặp trong bài toán. Viết sai ngay bước đầu thì cả bài sai theo.', '"x, y, z tỉ lệ với a, b, c" nghĩa là x/a = y/b = z/c, còn viết là x : y : z = a : b : c. Đại lượng cần tìm ở tử, số cho trước ở mẫu, giữ đúng thứ tự.', '[{"de":"Viết \"x, y tỉ lệ với 2 và 3\".","giai":"Cách nghĩ sai: 2x = 3y. Cách đúng: x/2 = y/3. (Nếu 2x = 3y thì x/3 = y/2, tức x, y tỉ lệ với 3 và 2.)"},{"de":"Viết x : y : z = 3 : 4 : 5 thành dãy tỉ số bằng nhau.","giai":"x/3 = y/4 = z/5."}]'::jsonb, '[{"de":"\"a, b tỉ lệ với 5 và 7\" viết là?","dapAn":"a/5 = b/7","giaiThich":"Đại lượng ở tử, số ở mẫu, đúng thứ tự."},{"de":"Từ 3x = 2y suy ra x, y tỉ lệ với hai số nào?","dapAn":"2 và 3","giaiThich":"3x = 2y ⇒ x/2 = y/3."}]'::jsonb),
  ('VBH-DTS-02', 'Tính chất dãy tỉ số bằng nhau cho phép gộp các tỉ số lại. Nhưng phải gộp "đồng bộ": tử làm gì thì mẫu làm đúng như thế.', 'a/b = c/d = e/f = (a + c + e)/(b + d + f) = (a − c + e)/(b − d + f) (các mẫu khác 0). Không nhân các tử với nhau, không để tử trừ mà mẫu cộng.', '[{"de":"Cho x/5 = y/3, x − y = 8. Tìm x, y.","giai":"Cách nghĩ sai: x/5 = y/3 = (x − y)/(5 + 3) = 1. Cách đúng: (x − y)/(5 − 3) = 8/2 = 4 ⇒ x = 20; y = 12. Kiểm tra: 20 − 12 = 8."},{"de":"Cho x/2 = y/3 = z/4, x + y + z = 27.","giai":"x/2 = y/3 = z/4 = 27/9 = 3 ⇒ x = 6; y = 9; z = 12."}]'::jsonb, '[{"de":"x/3 = y/5, x + y = 16. Tìm x.","dapAn":"x = 6","giaiThich":"x/3 = y/5 = 16/8 = 2."},{"de":"x/7 = y/4, x − y = 9. Tìm y.","dapAn":"y = 12","giaiThich":"x/7 = y/4 = 9/3 = 3."}]'::jsonb),
  ('VBH-DTS-03', 'Khi đề cho tổng có hệ số như 2x + y hay 2x + 3y, nhiều bạn vẫn cộng thẳng các mẫu. Phải đưa hệ số vào tỉ số trước.', 'Muốn có 2x ở tử: x/2 = 2x/4 (nhân cả tử và mẫu với 2). Muốn có 3y: y/4 = 3y/12. Sau đó mới cộng (trừ) tử với tử, mẫu với mẫu.', '[{"de":"x/2 = y/3 và 2x + y = 14. Tìm x, y.","giai":"Cách nghĩ sai: (2x + y)/(2 + 3) = 14/5. Cách đúng: 2x/4 = y/3 = (2x + y)/(4 + 3) = 14/7 = 2 ⇒ x = 4; y = 6. Kiểm tra: 2 · 4 + 6 = 14."},{"de":"x/3 = y/4 và 2x + 3y = 36.","giai":"2x/6 = 3y/12 = (2x + 3y)/18 = 2 ⇒ x = 6; y = 8."}]'::jsonb, '[{"de":"x/1 = y/2 và 3x + y = 15. Tìm x.","dapAn":"x = 3","giaiThich":"3x/3 = y/2 = 15/5 = 3."},{"de":"x/2 = y/5 và x + 2y = 24. Tìm y.","dapAn":"y = 10","giaiThich":"x/2 = 2y/10 = 24/12 = 2."}]'::jsonb),
  ('VBH-DTS-04', 'Bài toán chia tỉ lệ có lời văn chỉ khó ở bước đọc đề: đại lượng nào ứng với số nào.', 'Bước 1: gọi tên các đại lượng theo thứ tự đề. Bước 2: viết dãy tỉ số giữ thứ tự đó. Bước 3: dùng tổng (hiệu) để tìm giá trị chung. Bước 4: kiểm tra lại với dữ kiện.', '[{"de":"Ba lớp 7A, 7B, 7C trồng 60 cây, tỉ lệ với 3; 4; 5. Lớp 7C trồng bao nhiêu cây?","giai":"Cách nghĩ sai: cho 7A ứng với 5, ra 7C trồng 15 cây. Cách đúng: a/3 = b/4 = c/5 = 60/12 = 5 ⇒ c = 25 cây."},{"de":"Anh hơn em 6 tuổi, tuổi anh và em tỉ lệ với 5 và 3.","giai":"a/5 = e/3 = (a − e)/2 = 3 ⇒ anh 15 tuổi, em 9 tuổi."}]'::jsonb, '[{"de":"Chia 40 viên bi cho hai bạn theo tỉ lệ 3 : 5. Bạn được ít hơn có mấy viên?","dapAn":"15 viên","giaiThich":"40 : 8 = 5; 3 · 5 = 15."},{"de":"Chu vi tam giác 36 cm, các cạnh tỉ lệ 3; 4; 5. Cạnh nhỏ nhất dài?","dapAn":"9 cm","giaiThich":"36 : 12 = 3; 3 · 3 = 9."}]'::jsonb),
  ('VBH-TLTH-01', '"Cùng tăng" là dấu hiệu dễ thấy nhưng chưa đủ để kết luận tỉ lệ thuận.', 'y tỉ lệ thuận với x khi y = kx (k ≠ 0). Cách kiểm tra bằng bảng: tính y/x cho mọi cặp giá trị; nếu luôn bằng cùng một số k thì tỉ lệ thuận.', '[{"de":"y = x + 3 có phải y tỉ lệ thuận với x không?","giai":"Cách nghĩ sai: x tăng thì y tăng nên tỉ lệ thuận. Cách đúng: x = 1 thì y/x = 4; x = 3 thì y/x = 2. Thương thay đổi nên không tỉ lệ thuận."},{"de":"Bảng x = 1; 2; 3 và y = 4; 8; 12.","giai":"y/x luôn bằng 4 nên y tỉ lệ thuận với x theo hệ số 4 (y = 4x)."}]'::jsonb, '[{"de":"y = 7x. y có tỉ lệ thuận với x không?","dapAn":"Có, hệ số 7","giaiThich":"Có dạng y = kx."},{"de":"Bảng x = 2; 4 và y = 5; 9. Có tỉ lệ thuận không?","dapAn":"Không","giaiThich":"5/2 = 2,5 khác 9/4 = 2,25."}]'::jsonb),
  ('VBH-TLTH-02', 'Đảo chiều "y theo x" thành "x theo y" thì hệ số cũng phải đảo.', 'Nếu y = kx thì x = (1/k)y. Vậy: y tỉ lệ thuận với x theo hệ số k ⇔ x tỉ lệ thuận với y theo hệ số 1/k.', '[{"de":"y = 3x. x tỉ lệ thuận với y theo hệ số nào?","giai":"Cách nghĩ sai: hệ số 3. Cách đúng: x = y : 3 = (1/3)y, hệ số 1/3."},{"de":"y tỉ lệ thuận với x theo hệ số −2/5. x tỉ lệ thuận với y theo hệ số nào?","giai":"x = (−5/2)y, hệ số −5/2."}]'::jsonb, '[{"de":"y = 4x. Hệ số của x đối với y?","dapAn":"1/4","giaiThich":"x = y : 4."},{"de":"x = −2y. Hệ số của y đối với x?","dapAn":"−1/2","giaiThich":"y = x : (−2)."}]'::jsonb),
  ('VBH-TLTH-03', 'Hai loại tỉ lệ có hai tính chất "ngược nhau": một bên thương không đổi, một bên tích không đổi. Lẫn hai tính chất là sai cả bài.', 'Tỉ lệ thuận: y1/x1 = y2/x2 = k và x1/x2 = y1/y2. Tìm y mới: y = k · x mới.', '[{"de":"x = 2 thì y = 6 (tỉ lệ thuận). x = 3 thì y = ?","giai":"Cách nghĩ sai: dùng tích, y = 2 · 6 : 3 = 4. Cách đúng: k = 6 : 2 = 3, y = 3 · 3 = 9."},{"de":"x1 = 4, x2 = 10, y1 = 6 (tỉ lệ thuận). Tìm y2.","giai":"x1/x2 = y1/y2 ⇒ 4/10 = 6/y2 ⇒ y2 = 15."}]'::jsonb, '[{"de":"x = 5 thì y = 20 (tỉ lệ thuận). x = 2 thì y = ?","dapAn":"8","giaiThich":"k = 4."},{"de":"x tăng gấp 3 (tỉ lệ thuận) thì y?","dapAn":"Tăng gấp 3","giaiThich":"y = kx."}]'::jsonb),
  ('VBH-TLTH-04', 'Trong bài toán tỉ lệ thuận, sai thường do xếp các giá trị không tương ứng vào tỉ lệ thức.', 'Lập bảng hai hàng, các giá trị tương ứng nằm cùng cột. Tỉ lệ thuận: các thương bằng nhau. Sau khi tính, kiểm tra hợp lí: đại lượng này tăng thì đại lượng kia cũng tăng.', '[{"de":"5 m dây nặng 120 g. 8 m dây nặng bao nhiêu?","giai":"Cách nghĩ sai: x = 5 · 120 : 8 = 75 g (dây dài hơn mà nhẹ hơn là vô lí). Cách đúng: 120/5 = x/8 ⇒ x = 192 g."},{"de":"3 quyển vở giá 24 000 đồng. 5 quyển giá bao nhiêu?","giai":"24 000 : 3 = 8 000 đồng/quyển; 5 quyển 40 000 đồng."}]'::jsonb, '[{"de":"4 phút in 120 trang. 10 phút in?","dapAn":"300 trang","giaiThich":"30 trang mỗi phút."},{"de":"2 kg dâu cần 3 kg đường. 5 kg dâu cần?","dapAn":"7,5 kg","giaiThich":"1,5 kg đường cho 1 kg dâu."}]'::jsonb),
  ('VBH-TLN-01', '"Một tăng một giảm" chưa đủ để là tỉ lệ nghịch. Phải kiểm tra tích.', 'y tỉ lệ nghịch với x khi y = a/x hay xy = a (a ≠ 0). Kiểm tra bằng bảng: tính xy cho mọi cặp; nếu luôn bằng cùng một số a thì tỉ lệ nghịch.', '[{"de":"y = 10 − x có phải tỉ lệ nghịch không?","giai":"Cách nghĩ sai: x tăng thì y giảm nên tỉ lệ nghịch. Cách đúng: x = 1 thì xy = 9; x = 5 thì xy = 25. Tích thay đổi nên không tỉ lệ nghịch."},{"de":"Bảng x = 1; 2; 4 và y = 20; 10; 5.","giai":"xy luôn bằng 20 nên y tỉ lệ nghịch với x theo hệ số 20."}]'::jsonb, '[{"de":"xy = 15. y có tỉ lệ nghịch với x không?","dapAn":"Có, hệ số 15","giaiThich":"Tích không đổi."},{"de":"Bảng x = 2; 3 và y = 9; 8. Có tỉ lệ nghịch không?","dapAn":"Không","giaiThich":"2 · 9 = 18 khác 3 · 8 = 24."}]'::jsonb),
  ('VBH-TLN-02', 'Với tỉ lệ nghịch, tỉ số phải đảo ngược. Đây là chỗ khác hẳn tỉ lệ thuận.', 'Tỉ lệ nghịch: x1y1 = x2y2 = a, và x1/x2 = y2/y1. Tìm y mới: y = a : x mới. x gấp k lần thì y giảm k lần.', '[{"de":"x = 2 thì y = 6 (tỉ lệ nghịch). x = 3 thì y = ?","giai":"Cách nghĩ sai: dùng tỉ số như tỉ lệ thuận, y = 9. Cách đúng: a = 2 · 6 = 12, y = 12 : 3 = 4."},{"de":"x1 = 4, x2 = 6, y1 = 9 (tỉ lệ nghịch). Tìm y2.","giai":"4 · 9 = 6 · y2 ⇒ y2 = 6."}]'::jsonb, '[{"de":"x = 5 thì y = 8 (tỉ lệ nghịch). x = 10 thì y = ?","dapAn":"4","giaiThich":"a = 40."},{"de":"x tăng gấp 4 (tỉ lệ nghịch) thì y?","dapAn":"Giảm 4 lần","giaiThich":"xy không đổi."}]'::jsonb),
  ('VBH-TLN-03', 'Bài toán thực tế không ghi sẵn "tỉ lệ thuận" hay "tỉ lệ nghịch". Em phải tự hỏi một câu trước khi tính.', 'Câu hỏi then chốt: "Nếu đại lượng này gấp đôi thì đại lượng kia gấp đôi hay giảm một nửa?". Gấp đôi → tỉ lệ thuận. Giảm một nửa → tỉ lệ nghịch. Cùng một công việc: số người và số ngày tỉ lệ nghịch. Cùng quãng đường: vận tốc và thời gian tỉ lệ nghịch.', '[{"de":"4 người làm xong việc trong 6 ngày. 8 người làm xong trong mấy ngày?","giai":"Cách nghĩ sai: gấp đôi người thì gấp đôi ngày, 12 ngày. Cách đúng: nhiều người hơn thì nhanh hơn, tỉ lệ nghịch: 4 · 6 = 8 · x ⇒ x = 3 ngày."},{"de":"Ô tô đi 40 km/h hết 3 giờ. Đi 60 km/h hết mấy giờ?","giai":"Cùng quãng đường, vận tốc và thời gian tỉ lệ nghịch: 40 · 3 = 60 · t ⇒ t = 2 giờ."}]'::jsonb, '[{"de":"6 người sơn xong tường trong 10 giờ. 3 người cần?","dapAn":"20 giờ","giaiThich":"Tỉ lệ nghịch: 6 · 10 = 3 · t."},{"de":"Số quyển vở và số tiền phải trả (cùng loại vở) là tương quan gì?","dapAn":"Tỉ lệ thuận","giaiThich":"Mua gấp đôi thì trả gấp đôi."}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

