-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-BTDS-01', 'C7-B24-M1', 'Viết biểu thức đại số từ lời văn sai thứ tự phép tính, thiếu dấu ngoặc khi cần tính tổng (hiệu) trước. Ví dụ: "Tổng của a và b nhân với 2" viết thành a + b · 2', 'VBH-BTDS-01'),
  ('E-BTDS-02', 'C7-B24-M1', 'Hiểu sai quy ước của biểu thức đại số: coi 2x là 2 + x, x² là 2x, hoặc không phân biệt biểu thức số với biểu thức đại số. Ví dụ: Với x = 3 tính 2x = 23 hoặc x² = 6', 'VBH-BTDS-02'),
  ('E-GTBT-01', 'C7-B24-M2', 'Thay giá trị âm của biến mà không đặt trong ngoặc nên sai dấu khi tính lũy thừa và nhân. Ví dụ: x = −3 thì x² = −9', 'VBH-GTBT-01'),
  ('E-GTBT-02', 'C7-B24-M2', 'Tính giá trị biểu thức không theo thứ tự: cộng trước rồi mới nhân, hoặc tính lũy thừa sau. Ví dụ: 2 + 3x tại x = 4 tính (2 + 3) · 4 = 20', 'VBH-GTBT-02'),
  ('E-DTH-01', 'C7-B25-M1', 'Nhận diện đơn thức một biến sai: coi tổng (x + 1) hay thương có biến ở mẫu (1/x) là đơn thức, hoặc cho rằng một số không phải đơn thức. Ví dụ: Cho rằng 2x + 1 là đơn thức, còn 5 không phải đơn thức', 'VBH-DTH-01'),
  ('E-DTH-02', 'C7-B25-M1', 'Cộng hai đơn thức cùng bậc mà cộng cả số mũ; nhân hai lũy thừa mà nhân số mũ hoặc cộng hệ số. Ví dụ: 2x² + 3x² = 5x⁴; x² · x³ = x⁶', 'VBH-DTH-02'),
  ('E-DAT-01', 'C7-B25-M2', 'Thu gọn đa thức mà gộp các hạng tử khác bậc, hoặc bỏ sót dấu "−" của hạng tử. Ví dụ: 3x² + 2x = 5x³; 3x² − x² = 4x²', 'VBH-DAT-01'),
  ('E-DAT-02', 'C7-B25-M2', 'Sắp xếp đa thức mà bỏ dấu "−" khi đổi chỗ hạng tử, hoặc sắp theo hệ số thay vì theo số mũ. Ví dụ: −3x + 4x² − 1 sắp xếp thành 4x² + 3x − 1', 'VBH-DAT-02'),
  ('E-BAC-01', 'C7-B25-M3', 'Xác định bậc khi chưa thu gọn, cộng các số mũ để lấy bậc, hoặc cho rằng đa thức không có bậc 0. Ví dụ: P(x) = x⁴ + 2x − x⁴ có bậc 4', 'VBH-BAC-01'),
  ('E-BAC-02', 'C7-B25-M3', 'Lấy hệ số của hạng tử viết đầu tiên (chưa sắp xếp) làm hệ số cao nhất, quên dấu, hoặc nhầm hệ số tự do. Ví dụ: 3x − 4x³ + 1 có hệ số cao nhất là 3', 'VBH-BAC-02'),
  ('E-NGH-01', 'C7-B25-M4', 'Nhầm nghiệm của đa thức với giá trị P(0) hay với hệ số tự do; không thay số vào để kiểm tra P(a) = 0. Ví dụ: Nghiệm của 2x − 6 là −6', 'VBH-NGH-01'),
  ('E-NGH-02', 'C7-B25-M4', 'Cho rằng đa thức nào cũng có nghiệm, hoặc số nghiệm luôn bằng bậc. Ví dụ: x² + 1 có nghiệm x = −1', 'VBH-NGH-02'),
  ('E-CONG-01', 'C7-B26-M1', 'Cộng đa thức theo cột dọc mà đặt các hạng tử khác bậc thẳng cột (không chừa chỗ cho bậc khuyết), hoặc gộp nhầm hạng tử khác bậc. Ví dụ: x³ − 2x + 1 cộng 2x² + 2x − 3 viết cột x³ thẳng 2x²', 'VBH-CONG-01'),
  ('E-TRU-01', 'C7-B26-M2', 'Khi trừ đa thức, bỏ ngoặc có dấu "−" đằng trước nhưng chỉ đổi dấu hạng tử đầu tiên. Ví dụ: (3x² + 2x) − (x² − x) = 2x² + x', 'VBH-TRU-01'),
  ('E-NHAN-01', 'C7-B27-M1', 'Nhân đơn thức với đa thức nhưng chỉ nhân với hạng tử đầu, hoặc sai dấu khi nhân với hạng tử âm. Ví dụ: 2x(x + 3) = 2x² + 3', 'VBH-NHAN-01'),
  ('E-NHAN-02', 'C7-B27-M2', 'Nhân đa thức với đa thức nhưng chỉ nhân các hạng tử "cùng vị trí", bỏ sót tích riêng. Ví dụ: (x + 2)(x + 3) = x² + 6', 'VBH-NHAN-02'),
  ('E-CHIA-01', 'C7-B28-M1', 'Chia đơn thức cho đơn thức mà chia các số mũ (hoặc cộng số mũ), hoặc trừ hệ số thay vì chia. Ví dụ: x⁶ : x² = x³; 6x⁵ : 2x³ = 4x²', 'VBH-CHIA-01'),
  ('E-CHIA-02', 'C7-B28-M2', 'Chia đa thức cho đa thức không sắp xếp giảm dần, không chừa chỗ hạng tử khuyết, trừ sai dấu ở mỗi bước, hoặc chia đa thức cho đơn thức chỉ chia hạng tử đầu. Ví dụ: (x³ − 1) : (x − 1) = x² + 1', 'VBH-CHIA-02'),
  ('E-CHIA-03', 'C7-B28-M3', 'Dừng phép chia khi dư còn có bậc lớn hơn hoặc bằng bậc đa thức chia, hoặc nhầm vai trò thương, dư trong A = B · Q + R. Ví dụ: Chia x³ + x² + 4 cho x² + 1, dừng ở dư x² − x + 4', 'VBH-CHIA-03')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh) values
  ('C7-B24-M1-Q01', 'C7-B24-M1', 1, 'Biểu thức đại số biểu thị "tổng của x và 5" là:', 'A', 45, null),
  ('C7-B24-M1-Q02', 'C7-B24-M1', 1, 'Trong các biểu thức sau, biểu thức nào là biểu thức đại số?', 'A', 45, null),
  ('C7-B24-M1-Q03', 'C7-B24-M1', 2, 'Biểu thức biểu thị "hiệu của a và b, rồi nhân với 3" là:', 'A', 60, null),
  ('C7-B24-M1-Q04', 'C7-B24-M1', 2, 'Viết gọn biểu thức 2 · x · x · y:', 'A', 60, null),
  ('C7-B24-M1-Q05', 'C7-B24-M1', 3, 'Hình chữ nhật có chiều dài a (cm), chiều rộng ngắn hơn chiều dài 3 cm. Biểu thức biểu thị chu vi là:', 'A', 90, null),
  ('C7-B24-M1-Q06', 'C7-B24-M1', 3, 'Một quyển vở giá x đồng, một cái bút đắt hơn quyển vở 2 000 đồng. Mua 3 quyển vở và 2 cái bút hết:', 'A', 90, null),
  ('C7-B24-M1-Q07', 'C7-B24-M1', 4, 'Bạn Minh viết "bình phương của tổng a và b" là a² + b². Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C7-B24-M1-Q08', 'C7-B24-M1', 4, 'Bể có sẵn 200 lít nước. Mỗi phút vòi A chảy vào x lít, đồng thời vòi B chảy ra y lít (x > y). Lượng nước trong bể sau t phút là:', 'A', 120, null),
  ('C7-B24-M2-Q01', 'C7-B24-M2', 1, 'Giá trị của biểu thức 2x + 1 tại x = 3 là:', 'A', 45, null),
  ('C7-B24-M2-Q02', 'C7-B24-M2', 1, 'Giá trị của x² tại x = −3 là:', 'A', 45, null),
  ('C7-B24-M2-Q03', 'C7-B24-M2', 2, 'Giá trị của biểu thức 3x² − 2x tại x = −1 là:', 'A', 60, null),
  ('C7-B24-M2-Q04', 'C7-B24-M2', 2, 'Giá trị của biểu thức 2 + 3x tại x = 4 là:', 'A', 60, null),
  ('C7-B24-M2-Q05', 'C7-B24-M2', 3, 'Giá trị của biểu thức (x − y)² tại x = 2, y = −3 là:', 'A', 90, null),
