insert into error_hints (error_code, tier, hint_text) values
  ('E-BTDS-01', 1, 'Theo đề, phép tính nào phải làm TRƯỚC?'),
  ('E-BTDS-01', 2, 'Khi lời văn nói "tổng (hiệu) của … rồi nhân với …", phần tổng (hiệu) phải đặt trong ngoặc. Viết xong, em đọc ngược biểu thức thành lời để kiểm tra.'),
  ('E-BTDS-01', 3, 'Ví dụ: "hiệu của a và b, rồi nhân với 3" là (a − b) · 3. Viết a − b · 3 là "a trừ đi 3 lần b" — khác nghĩa.'),
  ('E-BTDS-02', 1, 'Trong 2x, giữa 2 và x là phép tính gì?'),
  ('E-BTDS-02', 2, 'Quy ước: 2x là 2 · x; x² là x · x; xy là x · y. Biểu thức số chỉ có số; biểu thức đại số có chữ (biến).'),
  ('E-BTDS-02', 3, 'Ví dụ: x = 3 thì 2x = 2 · 3 = 6 (không phải 23); x² = 3 · 3 = 9 (không phải 6).'),
  ('E-GTBT-01', 1, 'Em đã đặt số âm trong ngoặc khi thay vào chưa?'),
  ('E-GTBT-01', 2, 'Thay giá trị âm thì luôn viết trong ngoặc: x = −3 ⇒ x² = (−3)² = 9. Lũy thừa chẵn của số âm là số dương, lũy thừa lẻ là số âm.'),
  ('E-GTBT-01', 3, 'Ví dụ: 3x² − 2x tại x = −1: 3 · (−1)² − 2 · (−1) = 3 + 2 = 5.'),
  ('E-GTBT-02', 1, 'Trong biểu thức, có lũy thừa, nhân và cộng. Em làm phép nào trước?'),
  ('E-GTBT-02', 2, 'Thứ tự: trong ngoặc trước; rồi lũy thừa; rồi nhân, chia; cuối cùng cộng, trừ.'),
  ('E-GTBT-02', 3, 'Ví dụ: 2 + 3x tại x = 4: 3 · 4 = 12 trước, rồi 2 + 12 = 14 (không phải (2 + 3) · 4 = 20).'),
  ('E-DTH-01', 1, 'Biểu thức này có dấu cộng (trừ) giữa các phần, hoặc có biến ở mẫu không?'),
  ('E-DTH-01', 2, 'Đơn thức một biến là một số, hoặc một biến, hoặc tích của một số với lũy thừa của biến với số mũ tự nhiên (như −3x², 5, x). Tổng như x + 1 hay biểu thức 1/x không phải đơn thức.'),
  ('E-DTH-01', 3, 'Ví dụ: 5 và −x là đơn thức; x² + x là đa thức (có hai hạng tử); 1/x không phải đơn thức.'),
  ('E-DTH-02', 1, 'Khi cộng, số mũ có thay đổi không? Khi nhân, số mũ thay đổi thế nào?'),
  ('E-DTH-02', 2, 'Cộng (trừ) đơn thức cùng bậc: cộng (trừ) hệ số, GIỮ NGUYÊN phần biến. Nhân đơn thức: nhân hệ số, CỘNG số mũ (xᵐ · xⁿ = xᵐ⁺ⁿ).'),
  ('E-DTH-02', 3, 'Ví dụ: 2x² + 3x² = 5x² (không phải 5x⁴); x² · x³ = x⁵ (không phải x⁶).'),
  ('E-DAT-01', 1, 'Hai hạng tử em gộp có cùng số mũ không? Dấu đứng trước mỗi hạng tử là gì?'),
  ('E-DAT-01', 2, 'Chỉ gộp các hạng tử cùng bậc (cùng số mũ của biến). Mỗi hạng tử mang theo dấu đứng ngay trước nó.'),
  ('E-DAT-01', 3, 'Ví dụ: 3x² + 2x − x² + 4 = (3x² − x²) + 2x + 4 = 2x² + 2x + 4. Không gộp 2x² với 2x.'),
  ('E-DAT-02', 1, 'Khi chuyển hạng tử −3x lên chỗ khác, dấu "−" của nó đi đâu?'),
  ('E-DAT-02', 2, 'Sắp xếp theo lũy thừa giảm dần: số mũ lớn đứng trước. Mỗi hạng tử mang theo dấu của nó khi đổi chỗ.'),
  ('E-DAT-02', 3, 'Ví dụ: −3x + 4x² − 1 ⇒ 4x² − 3x − 1.'),
  ('E-BAC-01', 1, 'Đa thức đã thu gọn chưa? Có hạng tử nào triệt tiêu nhau không?'),
  ('E-BAC-01', 2, 'Bậc của đa thức là số mũ lớn nhất của biến trong dạng THU GỌN (không cộng các số mũ). Một số khác 0 là đa thức bậc 0; đa thức 0 không có bậc.'),
  ('E-BAC-01', 3, 'Ví dụ: x⁴ + 2x − x⁴ + 3 = 2x + 3, có bậc 1 (không phải 4).'),
  ('E-BAC-02', 1, 'Em đã sắp xếp đa thức theo lũy thừa giảm dần chưa?'),
  ('E-BAC-02', 2, 'Hệ số cao nhất là hệ số (kèm dấu) của hạng tử có bậc cao nhất; hệ số tự do là hạng tử không chứa biến.'),
  ('E-BAC-02', 3, 'Ví dụ: 3x − 4x³ + 1 = −4x³ + 3x + 1: hệ số cao nhất −4, hệ số tự do 1.'),
  ('E-NGH-01', 1, 'Em đã thay số đó vào đa thức để xem kết quả có bằng 0 không?'),
  ('E-NGH-01', 2, 'x = a là nghiệm của P(x) khi P(a) = 0. Muốn kiểm tra: thay a vào, tính P(a). Muốn tìm nghiệm của đa thức bậc nhất: giải P(x) = 0.'),
  ('E-NGH-01', 3, 'Ví dụ: 2x − 6 = 0 ⇒ x = 3. Kiểm tra P(3) = 6 − 6 = 0. Số −6 chỉ là P(0).'),
  ('E-NGH-02', 1, 'Biểu thức này có thể nhận giá trị 0 không? Em xét dấu của nó.'),
  ('E-NGH-02', 2, 'Không phải đa thức nào cũng có nghiệm. Ví dụ x² + 1 ≥ 1 > 0 với mọi x nên không có nghiệm. Số nghiệm không vượt quá bậc, nhưng có thể ít hơn.'),
  ('E-NGH-02', 3, 'Ví dụ: x = −1 thì x² + 1 = (−1)² + 1 = 2 ≠ 0, nên −1 không phải nghiệm.'),
  ('E-CONG-01', 1, 'Các hạng tử thẳng cột của em có cùng số mũ không?'),
  ('E-CONG-01', 2, 'Cộng theo cột: sắp xếp hai đa thức cùng chiều, đặt hạng tử cùng bậc thẳng cột; bậc nào khuyết thì để trống ô đó.'),
  ('E-CONG-01', 3, 'Ví dụ: x³ + 0x² − 2x + 1 và 2x² + 2x − 3 ⇒ x³ + 2x² + 0x − 2.'),
  ('E-TRU-01', 1, 'Trước ngoặc có dấu "−". Em đã đổi dấu những hạng tử nào trong ngoặc?'),
  ('E-TRU-01', 2, 'Bỏ ngoặc có dấu "−" đằng trước: đổi dấu TẤT CẢ hạng tử trong ngoặc (+ thành −, − thành +).'),
  ('E-TRU-01', 3, 'Ví dụ: (3x² + 2x) − (x² − x) = 3x² + 2x − x² + x = 2x² + 3x.'),
  ('E-NHAN-01', 1, 'Đơn thức đã được nhân với hạng tử thứ hai, thứ ba chưa?'),
  ('E-NHAN-01', 2, 'Nhân đơn thức với đa thức: nhân đơn thức với TỪNG hạng tử (kể cả dấu) rồi cộng các tích.'),
  ('E-NHAN-01', 3, 'Ví dụ: −3x(2x² − x + 4) = −6x³ + 3x² − 12x.'),
  ('E-NHAN-02', 1, 'Đa thức thứ nhất có mấy hạng tử, đa thức thứ hai có mấy hạng tử? Vậy có bao nhiêu tích riêng?'),
  ('E-NHAN-02', 2, 'Nhân mỗi hạng tử của đa thức này với TỪNG hạng tử của đa thức kia (2 × 2 = 4 tích, 2 × 3 = 6 tích), rồi thu gọn.'),
  ('E-NHAN-02', 3, 'Ví dụ: (x + 2)(x + 3) = x² + 3x + 2x + 6 = x² + 5x + 6.'),
  ('E-CHIA-01', 1, 'Khi chia hai lũy thừa cùng cơ số, số mũ thay đổi thế nào?'),
  ('E-CHIA-01', 2, 'axᵐ : bxⁿ = (a : b)xᵐ⁻ⁿ với m ≥ n: chia hệ số, TRỪ số mũ.'),
  ('E-CHIA-01', 3, 'Ví dụ: 6x⁵ : 2x³ = 3x² (không phải 4x² hay x⁵ᐟ³).'),
  ('E-CHIA-02', 1, 'Đa thức bị chia đã sắp xếp và chừa chỗ cho hạng tử khuyết chưa? Ở bước trừ, em đã đổi dấu chưa?'),
  ('E-CHIA-02', 2, 'Chia đa thức: sắp xếp giảm dần, chừa chỗ bậc khuyết; mỗi vòng: chia hạng tử bậc cao nhất → nhân ngược → trừ (đổi dấu) → hạ xuống. Chia đa thức cho đơn thức: chia từng hạng tử.'),
  ('E-CHIA-02', 3, 'Ví dụ: (x³ + 0x² + 0x − 1) : (x − 1) = x² + x + 1.'),
  ('E-CHIA-03', 1, 'Bậc của dư hiện tại so với bậc của đa thức chia thế nào?'),
  ('E-CHIA-03', 2, 'Chỉ dừng khi dư bằng 0 hoặc dư có bậc NHỎ HƠN bậc đa thức chia. Khi đó A = B · Q + R.'),
  ('E-CHIA-03', 3, 'Ví dụ: chia x³ + x² + 4 cho x² + 1: sau bước đầu dư x² − x + 4 vẫn bậc 2 nên chia tiếp, được thương x + 1, dư −x + 3.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-BTDS-01', 'Viết biểu thức từ lời văn giống như dịch một câu: sai thứ tự là sai nghĩa. Dấu ngoặc là công cụ giữ đúng thứ tự.', 'Đọc lời văn, xác định phép tính làm trước. Nếu "tổng" hoặc "hiệu" phải tính trước rồi mới nhân, chia, bình phương thì đặt nó trong ngoặc. Viết xong, đọc ngược biểu thức thành lời để kiểm tra.', '[{"de":"Viết \"tổng của a và b, nhân với 2\".","giai":"Cách nghĩ sai: a + b · 2 (đọc ngược là \"a cộng 2 lần b\"). Cách đúng: (a + b) · 2."},{"de":"Viết \"bình phương của tổng a và b\".","giai":"Tổng tính trước rồi bình phương: (a + b)². Còn a² + b² là \"tổng các bình phương\"."}]'::jsonb, '[{"de":"Viết \"hiệu của x và 3, chia cho 2\".","dapAn":"(x − 3) : 2","giaiThich":"Hiệu phải tính trước."},{"de":"Viết \"3 lần tổng của x và y\".","dapAn":"3(x + y)","giaiThich":"Tổng tính trước rồi nhân 3."}]'::jsonb),
  ('VBH-BTDS-02', 'Biểu thức đại số có những cách viết gọn. Hiểu sai quy ước thì thay số sẽ sai ngay.', 'Quy ước: 2x là 2 · x; xy là x · y; x² là x · x; x³ là x · x · x. Biểu thức số chỉ gồm số và phép tính; biểu thức đại số có thêm chữ (biến).', '[{"de":"Tính 2x và x² khi x = 3.","giai":"Cách nghĩ sai: 2x = 23, x² = 3 · 2 = 6. Cách đúng: 2x = 2 · 3 = 6; x² = 3 · 3 = 9."},{"de":"Viết gọn 3 · x · x · y.","giai":"3x²y."}]'::jsonb, '[{"de":"Với x = 5, 4x bằng?","dapAn":"20","giaiThich":"4 · 5."},{"de":"3 + 4 · 5 là biểu thức số hay biểu thức đại số?","dapAn":"Biểu thức số","giaiThich":"Không có chữ."}]'::jsonb),
  ('VBH-GTBT-01', 'Thay số âm vào biểu thức mà quên ngoặc là lỗi rất hay gặp, nhất là với lũy thừa.', 'Khi thay giá trị âm, luôn viết nó trong ngoặc: x = −3 ⇒ x² = (−3)² = 9; x³ = (−3)³ = −27. Lũy thừa chẵn của số âm dương, lũy thừa lẻ âm.', '[{"de":"Tính x² tại x = −3.","giai":"Cách nghĩ sai: −3² = −9. Cách đúng: (−3)² = (−3) · (−3) = 9."},{"de":"Tính 3x² − 2x tại x = −1.","giai":"3 · (−1)² − 2 · (−1) = 3 · 1 + 2 = 5."}]'::jsonb, '[{"de":"x³ tại x = −2 bằng?","dapAn":"−8","giaiThich":"(−2)³ = −8."},{"de":"x² − x tại x = −2 bằng?","dapAn":"6","giaiThich":"4 − (−2) = 6."}]'::jsonb),
  ('VBH-GTBT-02', 'Tính giá trị biểu thức đại số cũng theo đúng thứ tự như biểu thức số.', 'Thứ tự: trong ngoặc → lũy thừa → nhân, chia → cộng, trừ (từ trái sang phải).', '[{"de":"Tính 2 + 3x tại x = 4.","giai":"Cách nghĩ sai: (2 + 3) · 4 = 20. Cách đúng: 3 · 4 = 12, rồi 2 + 12 = 14."},{"de":"Tính 10 000 + 12 000x tại x = 7,5.","giai":"12 000 · 7,5 = 90 000; 10 000 + 90 000 = 100 000."}]'::jsonb, '[{"de":"5 − 2x tại x = 1 bằng?","dapAn":"3","giaiThich":"2 · 1 = 2; 5 − 2 = 3."},{"de":"1 + x² tại x = 3 bằng?","dapAn":"10","giaiThich":"3² = 9; 1 + 9."}]'::jsonb),
  ('VBH-DTH-01', 'Đơn thức là "viên gạch" của đa thức. Nhận ra đúng viên gạch thì mới xây được.', 'Đơn thức một biến: một số, một biến, hoặc tích của một số với lũy thừa của biến với số mũ tự nhiên (ví dụ 5; x; −3x²; (1/2)x⁴). Biểu thức có dấu cộng, trừ giữa các phần (x + 1) là đa thức; biểu thức có biến ở mẫu (1/x) không phải đơn thức.', '[{"de":"2x + 1 có phải đơn thức không?","giai":"Cách nghĩ sai: có biến nên là đơn thức. Cách đúng: 2x + 1 có hai hạng tử nối bằng dấu cộng, nên là đa thức, không phải đơn thức."},{"de":"Số 5 có phải đơn thức không?","giai":"Có. Mỗi số là một đơn thức."}]'::jsonb, '[{"de":"−x có phải đơn thức không?","dapAn":"Có","giaiThich":"Là tích của −1 với x."},{"de":"x² + x có phải đơn thức không?","dapAn":"Không","giaiThich":"Có hai hạng tử."}]'::jsonb),
  ('VBH-DTH-02', 'Cộng và nhân đơn thức có hai quy tắc khác nhau về số mũ. Nhầm hai quy tắc này kéo theo sai cả chương.', 'Cộng, trừ đơn thức cùng bậc: cộng, trừ hệ số và GIỮ NGUYÊN phần biến (axⁿ + bxⁿ = (a + b)xⁿ). Nhân hai đơn thức: nhân hệ số và CỘNG số mũ (axᵐ · bxⁿ = abxᵐ⁺ⁿ).', '[{"de":"2x² + 3x² bằng bao nhiêu?","giai":"Cách nghĩ sai: 5x⁴ (cộng cả số mũ). Cách đúng: hai đơn thức cùng là \"x²\", cộng hệ số: 5x²."},{"de":"(−2x²) · (3x³) bằng bao nhiêu?","giai":"(−2) · 3 = −6; x² · x³ = x⁵. Kết quả −6x⁵."}]'::jsonb, '[{"de":"4x³ − x³ bằng?","dapAn":"3x³","giaiThich":"Giữ phần biến."},{"de":"x · x⁴ bằng?","dapAn":"x⁵","giaiThich":"Cộng số mũ 1 + 4."}]'::jsonb),
  ('VBH-DAT-01', 'Thu gọn đa thức là gộp các hạng tử "cùng loại". Gộp nhầm loại là lỗi phổ biến nhất.', 'Chỉ gộp các hạng tử cùng bậc (cùng số mũ của biến). Mỗi hạng tử mang theo dấu đứng trước nó.', '[{"de":"Thu gọn 3x² + 2x − x² + 4.","giai":"Cách nghĩ sai: 3x² + 2x = 5x³, hoặc 3x² − x² = 4x². Cách đúng: (3x² − x²) + 2x + 4 = 2x² + 2x + 4."},{"de":"Thu gọn 5x³ − 2x + x³ + 2x − 1.","giai":"(5x³ + x³) + (−2x + 2x) − 1 = 6x³ − 1."}]'::jsonb, '[{"de":"Thu gọn x² + 3x − 2x².","dapAn":"−x² + 3x","giaiThich":"1 − 2 = −1."},{"de":"Thu gọn 4 − x + 2x − 1.","dapAn":"x + 3","giaiThich":"−x + 2x = x; 4 − 1 = 3."}]'::jsonb),
  ('VBH-DAT-02', 'Đổi chỗ hạng tử để sắp xếp thì dấu phải "đi theo" hạng tử.', 'Sắp xếp theo lũy thừa giảm dần: số mũ lớn đứng trước, số mũ nhỏ đứng sau, hằng số cuối cùng. Mỗi hạng tử giữ nguyên dấu của nó.', '[{"de":"Sắp xếp −3x + 4x² − 1 theo lũy thừa giảm dần.","giai":"Cách nghĩ sai: 4x² + 3x − 1 (mất dấu \"−\" của −3x). Cách đúng: 4x² − 3x − 1."},{"de":"Sắp xếp 2x − 5 + x³ − 3x² theo lũy thừa giảm dần.","giai":"x³ − 3x² + 2x − 5."}]'::jsonb, '[{"de":"Sắp xếp giảm dần: 1 − x² + 2x.","dapAn":"−x² + 2x + 1","giaiThich":"Giữ dấu −x²."},{"de":"Sắp xếp tăng dần: x³ − 2x + 5.","dapAn":"5 − 2x + x³","giaiThich":"Hằng số trước."}]'::jsonb),
  ('VBH-BAC-01', 'Bậc của đa thức phải xét ở dạng thu gọn. Có khi hạng tử bậc cao "biến mất" sau khi thu gọn.', 'Bậc của đa thức (thu gọn) là số mũ lớn nhất của biến. Không cộng các số mũ. Một số khác 0 là đa thức bậc 0; đa thức 0 (đa thức không) không có bậc.', '[{"de":"Tìm bậc của x⁴ + 2x − x⁴ + 3.","giai":"Cách nghĩ sai: thấy x⁴ nên bậc 4. Cách đúng: thu gọn được 2x + 3, bậc 1."},{"de":"Tìm bậc của 5x³ − 2x + 7.","giai":"Số mũ lớn nhất là 3, bậc 3 (không phải 3 + 1 = 4)."}]'::jsonb, '[{"de":"Bậc của đa thức 7?","dapAn":"0","giaiThich":"Số khác 0."},{"de":"Bậc của 3x² − 3x² + x?","dapAn":"1","giaiThich":"Thu gọn còn x."}]'::jsonb),
  ('VBH-BAC-02', 'Hệ số cao nhất không phải là hệ số "đứng đầu" khi đa thức chưa sắp xếp.', 'Sắp xếp đa thức theo lũy thừa giảm dần. Hệ số cao nhất là hệ số (kèm dấu) của hạng tử bậc cao nhất; hệ số tự do là hạng tử không chứa biến.', '[{"de":"Tìm hệ số cao nhất của 3x − 4x³ + 1.","giai":"Cách nghĩ sai: 3 (đứng đầu). Cách đúng: sắp xếp −4x³ + 3x + 1, hệ số cao nhất −4."},{"de":"Tìm hệ số tự do của 2x³ − x + 4.","giai":"Hạng tử không chứa biến là 4, hệ số tự do 4."}]'::jsonb, '[{"de":"Hệ số cao nhất của 5 − x²?","dapAn":"−1","giaiThich":"−x² = −1 · x²."},{"de":"Hệ số tự do của x² − 3x?","dapAn":"0","giaiThich":"Không có hạng tử tự do."}]'::jsonb),
  ('VBH-NGH-01', 'Nghiệm của đa thức là con số làm cho đa thức bằng 0, không phải giá trị P(0).', 'x = a là nghiệm của P(x) khi P(a) = 0. Kiểm tra: thay a vào và tính. Tìm nghiệm đa thức bậc nhất ax + b: giải ax + b = 0.', '[{"de":"Tìm nghiệm của P(x) = 2x − 6.","giai":"Cách nghĩ sai: nghiệm là −6 (đó là P(0)). Cách đúng: 2x − 6 = 0 ⇒ x = 3; kiểm tra P(3) = 0."},{"de":"x = 2 có là nghiệm của x² − 4 không?","giai":"P(2) = 4 − 4 = 0 nên có."}]'::jsonb, '[{"de":"Nghiệm của 3x + 9?","dapAn":"x = −3","giaiThich":"3x = −9."},{"de":"x = 1 có là nghiệm của x² + x không?","dapAn":"Không","giaiThich":"P(1) = 2 ≠ 0."}]'::jsonb),
  ('VBH-NGH-02', 'Không phải đa thức nào cũng có nghiệm. Có những đa thức luôn dương.', 'Nếu P(x) luôn lớn hơn 0 (hoặc luôn nhỏ hơn 0) với mọi x thì P(x) không có nghiệm. Ví dụ x² ≥ 0 nên x² + 1 ≥ 1 > 0. Số nghiệm của đa thức không vượt quá bậc của nó.', '[{"de":"x² + 1 có nghiệm x = −1 không?","giai":"Cách nghĩ sai: có. Cách đúng: (−1)² + 1 = 2 ≠ 0. Thật ra x² + 1 ≥ 1 với mọi x nên không có nghiệm."},{"de":"x² − 1 có những nghiệm nào?","giai":"1 và −1, vì 1 − 1 = 0 và (−1)² − 1 = 0."}]'::jsonb, '[{"de":"x² + 5 có nghiệm không?","dapAn":"Không","giaiThich":"x² + 5 ≥ 5."},{"de":"Đa thức bậc 2 có thể có bao nhiêu nghiệm?","dapAn":"Không quá 2","giaiThich":"Có thể 0, 1 hoặc 2."}]'::jsonb),
  ('VBH-CONG-01', 'Cộng đa thức theo cột rất gọn, nhưng chỉ đúng khi các hạng tử cùng bậc nằm thẳng cột.', 'Sắp xếp hai đa thức cùng chiều (giảm dần). Đặt hạng tử cùng bậc thẳng cột; bậc nào khuyết thì để trống (hoặc ghi 0). Cộng từng cột.', '[{"de":"Cộng x³ − 2x + 1 và 2x² + 2x − 3.","giai":"Cách nghĩ sai: đặt x³ thẳng với 2x², ra 3x³ − 2. Cách đúng: viết x³ + 0x² − 2x + 1 và 0x³ + 2x² + 2x − 3, cộng được x³ + 2x² − 2."},{"de":"Cộng (2x² + 3x) + (x² − x).","giai":"(2x² + x²) + (3x − x) = 3x² + 2x."}]'::jsonb, '[{"de":"(x² + 1) + (x − 1) = ?","dapAn":"x² + x","giaiThich":"Hạng tử tự do 1 − 1 = 0."},{"de":"Hệ số x² trong (3x³ + x) + (2x² − 1)?","dapAn":"2","giaiThich":"Chỉ đa thức thứ hai có x²."}]'::jsonb),
  ('VBH-TRU-01', 'Phép trừ đa thức sai chủ yếu vì một chỗ: bỏ ngoặc có dấu trừ.', 'Bỏ ngoặc có dấu "−" đằng trước: đổi dấu TẤT CẢ hạng tử trong ngoặc. Sau đó thu gọn như phép cộng.', '[{"de":"Tính (3x² + 2x) − (x² − x).","giai":"Cách nghĩ sai: chỉ đổi dấu x², được 2x² + x. Cách đúng: 3x² + 2x − x² + x = 2x² + 3x."},{"de":"Bỏ ngoặc −(2x² − 3x + 1).","giai":"−2x² + 3x − 1."}]'::jsonb, '[{"de":"(x² + 1) − (x² − 1) = ?","dapAn":"2","giaiThich":"x² − x² + 1 + 1."},{"de":"(5x − 2) − (3x − 4) = ?","dapAn":"2x + 2","giaiThich":"5x − 2 − 3x + 4."}]'::jsonb),
  ('VBH-NHAN-01', 'Nhân đơn thức với đa thức là "phân phối" cho mọi hạng tử, không bỏ sót ai.', 'A(B + C − D) = AB + AC − AD. Nhân đơn thức với TỪNG hạng tử, chú ý dấu và cộng số mũ.', '[{"de":"Tính 2x(x + 3).","giai":"Cách nghĩ sai: 2x² + 3 (quên nhân 2x với 3). Cách đúng: 2x · x + 2x · 3 = 2x² + 6x."},{"de":"Tính −3x(2x² − x + 4).","giai":"−6x³ + 3x² − 12x (nhân −3x với −x được +3x²)."}]'::jsonb, '[{"de":"x(x − 5) = ?","dapAn":"x² − 5x","giaiThich":"Nhân x với từng hạng tử."},{"de":"−2x(x + 1) = ?","dapAn":"−2x² − 2x","giaiThich":"Chú ý dấu."}]'::jsonb),
  ('VBH-NHAN-02', 'Nhân hai đa thức: mỗi hạng tử của đa thức này phải "gặp" mọi hạng tử của đa thức kia.', 'Nhân mỗi hạng tử của đa thức thứ nhất với từng hạng tử của đa thức thứ hai rồi cộng lại và thu gọn. Số tích riêng = số hạng tử thứ nhất × số hạng tử thứ hai.', '[{"de":"Tính (x + 2)(x + 3).","giai":"Cách nghĩ sai: x² + 6 (chỉ nhân \"cùng vị trí\"). Cách đúng: x · x + x · 3 + 2 · x + 2 · 3 = x² + 5x + 6."},{"de":"Tính (2x − 1)(x + 3).","giai":"2x² + 6x − x − 3 = 2x² + 5x − 3."}]'::jsonb, '[{"de":"(x − 1)(x + 1) = ?","dapAn":"x² − 1","giaiThich":"x² + x − x − 1."},{"de":"(x + 1)(x + 4) = ?","dapAn":"x² + 5x + 4","giaiThich":"4 tích riêng."}]'::jsonb),
  ('VBH-CHIA-01', 'Chia đơn thức là phép ngược của nhân đơn thức: nhân thì cộng số mũ, chia thì trừ số mũ.', 'axᵐ : bxⁿ = (a : b)xᵐ⁻ⁿ với m ≥ n và b ≠ 0. Chia hệ số cho hệ số, trừ số mũ.', '[{"de":"Tính 6x⁵ : 2x³.","giai":"Cách nghĩ sai: 4x² (trừ hệ số) hoặc 3x^(5/3) (chia số mũ). Cách đúng: 6 : 2 = 3; x⁵ : x³ = x²; kết quả 3x²."},{"de":"Tính (−12x⁴) : (4x).","giai":"−12 : 4 = −3; x⁴ : x = x³; kết quả −3x³."}]'::jsonb, '[{"de":"x⁶ : x² = ?","dapAn":"x⁴","giaiThich":"6 − 2 = 4."},{"de":"10x³ : (−5x) = ?","dapAn":"−2x²","giaiThich":"10 : (−5) = −2."}]'::jsonb),
  ('VBH-CHIA-02', 'Chia đa thức theo cột là một chuỗi bốn bước lặp lại. Sai một bước, sai cả phép chia.', 'Chuẩn bị: sắp xếp giảm dần, chừa chỗ hạng tử khuyết. Lặp: (1) chia hạng tử bậc cao nhất của bị chia cho hạng tử bậc cao nhất của số chia; (2) nhân kết quả với số chia; (3) trừ (đổi dấu); (4) hạ hạng tử tiếp theo. Chia đa thức cho đơn thức: chia từng hạng tử.', '[{"de":"Tính (x³ − 1) : (x − 1).","giai":"Cách nghĩ sai: không chừa chỗ cho x² và x, ra x² + 1. Cách đúng: viết x³ + 0x² + 0x − 1, chia được x² + x + 1."},{"de":"Tính (x² + 5x + 6) : (x + 2).","giai":"x² : x = x; x(x + 2) = x² + 2x; trừ còn 3x + 6; 3x : x = 3; 3(x + 2) = 3x + 6; trừ còn 0. Thương x + 3."}]'::jsonb, '[{"de":"(6x³ − 4x²) : 2x = ?","dapAn":"3x² − 2x","giaiThich":"Chia từng hạng tử."},{"de":"(x² − 9) : (x − 3) = ?","dapAn":"x + 3","giaiThich":"Viết x² + 0x − 9."}]'::jsonb),
  ('VBH-CHIA-03', 'Phép chia có dư dừng ở đâu? Không phải khi "trông có vẻ xong", mà khi bậc của dư nhỏ hơn bậc số chia.', 'Dừng khi dư bằng 0 hoặc có bậc nhỏ hơn bậc đa thức chia. Kết quả viết A = B · Q + R (B là đa thức chia, Q là thương, R là dư).', '[{"de":"Chia x³ + x² + 4 cho x² + 1.","giai":"Cách nghĩ sai: dừng ở thương x, dư x² − x + 4 (dư còn bậc 2 = bậc chia). Cách đúng: chia tiếp x² : x² = 1, thương x + 1, dư −x + 3 (bậc 1 < 2)."},{"de":"Chia x² + 3x + 5 cho x + 1.","giai":"x² + 3x + 5 = (x + 1)(x + 2) + 3: thương x + 2, dư 3."}]'::jsonb, '[{"de":"Chia x² + 1 cho x − 1, dư bằng?","dapAn":"2","giaiThich":"x² + 1 = (x − 1)(x + 1) + 2."},{"de":"Số chia bậc 2 thì dư có bậc tối đa là?","dapAn":"1","giaiThich":"Bậc dư nhỏ hơn bậc chia."}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

-- ===========================================================================
-- CHƯƠNG VIII — LÀM QUEN VỚI BIẾN CỐ VÀ XÁC SUẤT CỦA BIẾN CỐ
-- ===========================================================================
insert into knowledge_units (ku_id, lesson_id, ku_name, order_index, prerequisite_ku, co_video) values
  ('C8-B29-M1', 'Bài 29. Làm quen với biến cố', 'Mục 1–2. Biến cố chắc chắn, biến cố không thể, biến cố ngẫu nhiên', 89, null, true),
  ('C8-B30-M1', 'Bài 30. Làm quen với xác suất của biến cố', 'Mục 1. Xác suất của biến cố', 90, 'C8-B29-M1', true),
  ('C8-B30-M2', 'Bài 30. Làm quen với xác suất của biến cố', 'Mục 2. Xác suất của biến cố trong trò chơi đồng khả năng', 91, 'C8-B30-M1', true),
  ('C8-LTC', 'Luyện tập chung và Bài tập cuối chương VIII', 'Luyện tập chung Chương VIII', 92, 'C8-B30-M2', false)
