insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-BC-01', 'C8-B29-M1', 'Nhầm biến cố ngẫu nhiên với biến cố chắc chắn hoặc không thể (theo cảm giác "rất hay xảy ra", "hiếm khi xảy ra" hay theo vài lần thử). Ví dụ: Gieo xúc xắc 10 lần không ra mặt 6 nên "ra mặt 6" là biến cố không thể', 'VBH-BC-01'),
  ('E-BC-02', 'C8-B29-M1', 'Liệt kê thiếu hoặc thừa các kết quả có thể, hoặc các kết quả làm cho biến cố xảy ra. Ví dụ: Biến cố "mặt chẵn" của xúc xắc chỉ gồm mặt 2 và mặt 4', 'VBH-BC-02'),
  ('E-XS-01', 'C8-B30-M1', 'Cho xác suất là số lớn hơn 1, số âm hoặc số lần; không biết biến cố chắc chắn có xác suất 1, biến cố không thể có xác suất 0. Ví dụ: Xác suất mặt 6 chấm là 6; xác suất trời mưa là 1,2', 'VBH-XS-01'),
  ('E-XS-02', 'C8-B30-M1', 'So sánh khả năng xảy ra của các biến cố theo cảm tính (may mắn, số "đẹp"), không dựa vào số kết quả thuận lợi. Ví dụ: Túi có 8 bi đỏ, 2 bi xanh nhưng cho rằng khả năng lấy được hai màu như nhau', 'VBH-XS-02'),
  ('E-XS-03', 'C8-B30-M2', 'Tính xác suất bằng 1 chia cho số loại kết quả dù các loại đó không đồng khả năng, hoặc lấy số kết quả thuận lợi chia số kết quả không thuận lợi. Ví dụ: Hộp có 1 bi đỏ, 3 bi xanh: "đỏ hoặc xanh" nên xác suất lấy bi đỏ là 1/2', 'VBH-XS-03'),
  ('E-XS-04', 'C8-B30-M1', 'Cho rằng kết quả các lần trước làm thay đổi xác suất của lần sau, hoặc lấy tỉ lệ của vài lần thử làm xác suất. Ví dụ: Đồng xu ra ngửa 3 lần liền nên lần thứ tư chắc chắn ra sấp', 'VBH-XS-04')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh) values
  ('C8-B29-M1-Q01', 'C8-B29-M1', 1, 'Gieo một con xúc xắc. Biến cố "Mặt xuất hiện có số chấm nhỏ hơn 7" là:', 'A', 45, null),
  ('C8-B29-M1-Q02', 'C8-B29-M1', 1, 'Biến cố "Ngày mai Mặt Trời mọc ở hướng Tây" là:', 'A', 45, null),
  ('C8-B29-M1-Q03', 'C8-B29-M1', 2, 'Gieo một đồng xu. Biến cố "Đồng xu xuất hiện mặt sấp" là:', 'A', 60, null),
  ('C8-B29-M1-Q04', 'C8-B29-M1', 2, 'Một hộp chỉ có 5 bút xanh. Lấy ngẫu nhiên 1 bút. Biến cố nào là biến cố không thể?', 'A', 60, null),
  ('C8-B29-M1-Q05', 'C8-B29-M1', 3, 'Gieo một con xúc xắc. Biến cố "Mặt xuất hiện có số chấm là số chẵn" xảy ra khi mặt xuất hiện là:', 'A', 90, null),
  ('C8-B29-M1-Q06', 'C8-B29-M1', 3, 'Rút ngẫu nhiên 1 thẻ từ 10 thẻ ghi các số 1, 2, …, 10. Biến cố nào là biến cố ngẫu nhiên?', 'A', 90, null),
  ('C8-B29-M1-Q07', 'C8-B29-M1', 4, 'Lớp có 20 bạn nam và 15 bạn nữ. Chọn ngẫu nhiên 2 bạn. Biến cố "Trong hai bạn được chọn có bạn nam hoặc có bạn nữ" là:', 'A', 120, null),
  ('C8-B29-M1-Q08', 'C8-B29-M1', 4, 'Bạn Hùng nói: "Mình gieo xúc xắc 10 lần đều không ra mặt 6 chấm, vậy biến cố ra mặt 6 chấm là biến cố không thể". Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C8-B30-M1-Q01', 'C8-B30-M1', 1, 'Xác suất của một biến cố là một số:', 'A', 45, null),
  ('C8-B30-M1-Q02', 'C8-B30-M1', 1, 'Xác suất của biến cố chắc chắn bằng:', 'A', 45, null),
  ('C8-B30-M1-Q03', 'C8-B30-M1', 2, 'Xác suất của biến cố không thể bằng:', 'A', 60, null),
  ('C8-B30-M1-Q04', 'C8-B30-M1', 2, 'Túi có 8 viên bi đỏ và 2 viên bi xanh cùng kích thước. Lấy ngẫu nhiên 1 viên. Khẳng định nào ĐÚNG?', 'A', 60, null),
  ('C8-B30-M1-Q05', 'C8-B30-M1', 3, 'Gieo một xúc xắc. Biến cố nào có khả năng xảy ra lớn nhất?', 'A', 90, null),
  ('C8-B30-M1-Q06', 'C8-B30-M1', 3, 'Một đồng xu cân đối được gieo 3 lần đều ra mặt ngửa. Xác suất ra mặt ngửa ở lần gieo thứ tư là:', 'A', 90, null),
  ('C8-B30-M1-Q07', 'C8-B30-M1', 4, 'Bạn An nói: "Xác suất trời mưa ngày mai là 1,2". Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C8-B30-M1-Q08', 'C8-B30-M1', 4, 'Ba bạn lần lượt bốc ba lá thăm ghi số 1, 2, 3 (không trả lại). Bạn bốc đầu tiên nói: "Mình bốc trước nên khả năng được số 1 cao hơn hai bạn kia". Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C8-B30-M2-Q01', 'C8-B30-M2', 1, 'Gieo một xúc xắc cân đối. Xác suất xuất hiện mặt 5 chấm là:', 'A', 45, null),
  ('C8-B30-M2-Q02', 'C8-B30-M2', 1, 'Gieo một đồng xu cân đối. Xác suất xuất hiện mặt sấp là:', 'A', 45, null),
  ('C8-B30-M2-Q03', 'C8-B30-M2', 2, 'Hộp có 4 quả bóng màu đỏ, xanh, vàng, trắng cùng kích thước. Lấy ngẫu nhiên 1 quả. Xác suất lấy được quả màu vàng là:', 'A', 60, null),
  ('C8-B30-M2-Q04', 'C8-B30-M2', 2, 'Gieo xúc xắc cân đối. Sáu biến cố "mặt 1 chấm", …, "mặt 6 chấm" là đồng khả năng vì:', 'A', 60, null),
  ('C8-B30-M2-Q05', 'C8-B30-M2', 3, 'Gieo xúc xắc cân đối. Hai biến cố "mặt có số chấm lẻ" và "mặt có số chấm chẵn" đồng khả năng. Xác suất của biến cố "mặt có số chấm lẻ" là:', 'A', 90, null),
  ('C8-B30-M2-Q06', 'C8-B30-M2', 3, 'Một vòng quay chia thành 8 hình quạt bằng nhau đánh số từ 1 đến 8. Quay một lần, xác suất kim chỉ vào ô số 3 là:', 'A', 90, null),
  ('C8-B30-M2-Q07', 'C8-B30-M2', 4, 'Bạn Mai nói: "Hộp có 1 bi đỏ và 3 bi xanh cùng kích thước. Lấy 1 viên chỉ có hai khả năng đỏ hoặc xanh, nên xác suất lấy được bi đỏ là 1/2". Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C8-B30-M2-Q08', 'C8-B30-M2', 4, 'Một tấm bìa tròn chia thành 6 phần bằng nhau: 3 phần tô đỏ, 2 phần tô xanh, 1 phần tô vàng. Quay kim một lần. Xác suất kim chỉ vào phần màu vàng là:', 'A', 120, null),
  ('C8-LTC-Q01', 'C8-LTC', 1, 'Gieo một xúc xắc. Biến cố "Mặt xuất hiện có số chấm lớn hơn 0" là:', 'A', 45, null),
  ('C8-LTC-Q02', 'C8-LTC', 1, 'Có 5 lá thăm ghi các số 1, 2, 3, 4, 5. Rút ngẫu nhiên 1 lá. Xác suất rút được lá ghi số 2 là:', 'A', 45, null),
  ('C8-LTC-Q03', 'C8-LTC', 2, 'Gieo một xúc xắc. Biến cố nào có xác suất bằng 0?', 'A', 60, null),
  ('C8-LTC-Q04', 'C8-LTC', 2, 'Bạn Tâm gieo một đồng xu cân đối 10 lần được 7 lần ngửa, rồi nói: "Xác suất ra mặt ngửa của đồng xu này là 7/10". Nhận xét nào ĐÚNG?', 'A', 60, null),
  ('C8-LTC-Q05', 'C8-LTC', 3, 'Hộp có 6 thẻ ghi các số 1, 2, 3, 4, 5, 6. Rút 1 thẻ. Biến cố "Rút được thẻ ghi số chia hết cho 7" là:', 'A', 90, null),
  ('C8-LTC-Q06', 'C8-LTC', 3, 'Chọn ngẫu nhiên một ngày trong tuần. Xác suất chọn được ngày Chủ nhật là:', 'A', 90, null),
  ('C8-LTC-Q07', 'C8-LTC', 4, 'Gieo xúc xắc. Sắp xếp các biến cố theo khả năng xảy ra tăng dần: (1) mặt 6 chấm; (2) mặt có số chấm chẵn; (3) mặt có số chấm nhỏ hơn 7; (4) mặt 0 chấm.', 'A', 120, null),
  ('C8-LTC-Q08', 'C8-LTC', 4, 'Vòng quay chia 4 phần bằng nhau ghi "Thưởng", "Mất lượt", "Quay lại", "Thưởng". Bạn Nam nói: "Có 3 loại ô nên xác suất trúng Thưởng là 1/3". Nhận xét nào ĐÚNG?', 'A', 120, null)
on conflict (question_id) do update set ku_id = excluded.ku_id, level = excluded.level, stem = excluded.stem,
  correct_option = excluded.correct_option,
  expected_time_sec = excluded.expected_time_sec, hinh = excluded.hinh;

