insert into error_hints (error_code, tier, hint_text) values
  ('E-BC-01', 1, 'Biến cố này có lúc xảy ra, có lúc không, hay luôn luôn xảy ra, hay không bao giờ xảy ra?'),
  ('E-BC-01', 2, 'Biến cố chắc chắn: luôn xảy ra. Biến cố không thể: không bao giờ xảy ra. Biến cố ngẫu nhiên: có thể xảy ra, có thể không. Vài lần thử chưa đủ để kết luận "không thể".'),
  ('E-BC-01', 3, 'Ví dụ: gieo xúc xắc, "ra mặt 6" có thể xảy ra nên là ngẫu nhiên, dù 10 lần chưa ra; "ra mặt 7" không thể.'),
  ('E-BC-02', 1, 'Em đã liệt kê hết các kết quả có thể chưa? Kết quả nào làm cho biến cố xảy ra?'),
  ('E-BC-02', 2, 'Viết đủ tập các kết quả có thể (xúc xắc: 1, 2, 3, 4, 5, 6), rồi khoanh những kết quả làm biến cố xảy ra.'),
  ('E-BC-02', 3, 'Ví dụ: "mặt chẵn" xảy ra khi ra 2, 4 hoặc 6 chấm. Không có mặt 0 chấm.'),
  ('E-XS-01', 1, 'Xác suất có thể lớn hơn 1 không? Biến cố chắc chắn có xác suất bao nhiêu?'),
  ('E-XS-01', 2, 'Xác suất là số đo khả năng xảy ra, luôn từ 0 đến 1. Biến cố không thể: 0. Biến cố chắc chắn: 1. Biến cố ngẫu nhiên: lớn hơn 0 và nhỏ hơn 1.'),
  ('E-XS-01', 3, 'Ví dụ: xác suất ra mặt 6 chấm là 1/6, không phải 6.'),
  ('E-XS-02', 1, 'Biến cố nào có nhiều kết quả thuận lợi hơn?'),
  ('E-XS-02', 2, 'Với các kết quả đồng khả năng, biến cố có nhiều kết quả thuận lợi hơn thì có khả năng xảy ra lớn hơn. Không dựa vào "may mắn" hay "số đẹp".'),
  ('E-XS-02', 3, 'Ví dụ: 8 bi đỏ, 2 bi xanh: có 8 cách lấy được bi đỏ, chỉ 2 cách lấy được bi xanh, nên bi đỏ có khả năng lớn hơn.'),
  ('E-XS-03', 1, 'Các kết quả em đang đếm có đồng khả năng không?'),
  ('E-XS-03', 2, 'Chỉ khi có k biến cố đồng khả năng (và luôn xảy ra đúng một biến cố) thì mỗi biến cố có xác suất 1/k. Muốn vậy, em đếm theo từng viên bi, từng mặt, từng ô bằng nhau — không đếm theo "loại".'),
  ('E-XS-03', 3, 'Ví dụ: 1 bi đỏ, 3 bi xanh: bốn viên bi đồng khả năng nên xác suất lấy được viên bi đỏ là 1/4, không phải 1/2.'),
  ('E-XS-04', 1, 'Đồng xu có "nhớ" các lần gieo trước không?'),
  ('E-XS-04', 2, 'Mỗi lần gieo là độc lập: đồng xu cân đối luôn có xác suất ra ngửa là 1/2 ở mọi lần. Tỉ lệ của vài lần thử không phải là xác suất.'),
  ('E-XS-04', 3, 'Ví dụ: đã ra ngửa 3 lần, lần thứ tư xác suất ra ngửa vẫn là 1/2.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-BC-01', '"Hiếm khi xảy ra" không có nghĩa là "không thể", và "hay xảy ra" chưa phải là "chắc chắn".', 'Biến cố chắc chắn: luôn xảy ra. Biến cố không thể: không bao giờ xảy ra. Biến cố ngẫu nhiên: có thể xảy ra hoặc không. Phân loại dựa vào tất cả kết quả có thể, không dựa vào vài lần thử.', '[{"de":"Gieo xúc xắc 10 lần không ra mặt 6. \"Ra mặt 6\" là biến cố gì?","giai":"Cách nghĩ sai: biến cố không thể. Cách đúng: mặt 6 vẫn là một kết quả có thể, nên \"ra mặt 6\" là biến cố ngẫu nhiên."},{"de":"\"Gieo xúc xắc ra mặt có số chấm nhỏ hơn 7\" là biến cố gì?","giai":"Mọi mặt đều có số chấm từ 1 đến 6, nhỏ hơn 7. Đây là biến cố chắc chắn."}]'::jsonb, '[{"de":"\"Rút từ hộp chỉ có bi xanh được bi đỏ\" là?","dapAn":"Biến cố không thể","giaiThich":"Không có bi đỏ."},{"de":"\"Gieo đồng xu được mặt ngửa\" là?","dapAn":"Biến cố ngẫu nhiên","giaiThich":"Có thể ngửa hoặc sấp."}]'::jsonb),
  ('VBH-BC-02', 'Muốn biết biến cố xảy ra khi nào, trước hết phải liệt kê đủ các kết quả có thể.', 'Bước 1: liệt kê tất cả kết quả có thể. Bước 2: khoanh các kết quả làm cho biến cố xảy ra (kết quả thuận lợi). Kiểm tra không thiếu, không thừa.', '[{"de":"Biến cố \"mặt chẵn\" của xúc xắc xảy ra khi nào?","giai":"Cách nghĩ sai: mặt 2 hoặc 4 (thiếu mặt 6), hoặc thêm \"mặt 0\". Cách đúng: các kết quả có thể 1, 2, 3, 4, 5, 6; kết quả thuận lợi 2, 4, 6."},{"de":"Rút 1 thẻ từ các thẻ 1 đến 10. \"Rút được số nguyên tố\" xảy ra khi nào?","giai":"Rút được 2, 3, 5 hoặc 7."}]'::jsonb, '[{"de":"\"Mặt có số chấm lớn hơn 4\" gồm những mặt nào?","dapAn":"5 và 6","giaiThich":"Hai kết quả thuận lợi."},{"de":"Gieo đồng xu có mấy kết quả có thể?","dapAn":"2","giaiThich":"Sấp hoặc ngửa."}]'::jsonb),
  ('VBH-XS-01', 'Xác suất là "thước đo" khả năng xảy ra, và thước đo này chỉ đi từ 0 đến 1.', 'Mọi xác suất đều nằm trong đoạn từ 0 đến 1. Biến cố không thể có xác suất 0, biến cố chắc chắn có xác suất 1, biến cố ngẫu nhiên có xác suất lớn hơn 0 và nhỏ hơn 1.', '[{"de":"Xác suất ra mặt 6 chấm khi gieo xúc xắc cân đối là 6?","giai":"Cách nghĩ sai: lấy số chấm làm xác suất. Cách đúng: sáu mặt đồng khả năng, xác suất ra mặt 6 là 1/6."},{"de":"Xác suất trời mưa có thể là 1,2 không?","giai":"Không. Xác suất không lớn hơn 1."}]'::jsonb, '[{"de":"Xác suất của biến cố chắc chắn?","dapAn":"1","giaiThich":"Luôn xảy ra."},{"de":"Xác suất của biến cố không thể?","dapAn":"0","giaiThich":"Không bao giờ xảy ra."}]'::jsonb),
  ('VBH-XS-02', 'Khả năng xảy ra không phụ thuộc vào may mắn hay "số đẹp", mà phụ thuộc vào số kết quả thuận lợi.', 'Khi các kết quả đồng khả năng, biến cố có nhiều kết quả thuận lợi hơn thì có khả năng xảy ra lớn hơn.', '[{"de":"8 bi đỏ, 2 bi xanh: lấy 1 viên, màu nào có khả năng lớn hơn?","giai":"Cách nghĩ sai: như nhau vì đều là bi. Cách đúng: có 8 viên đỏ, 2 viên xanh nên khả năng lấy được bi đỏ lớn hơn."},{"de":"Gieo xúc xắc: \"mặt 6\" hay \"mặt chẵn\" có khả năng lớn hơn?","giai":"\"Mặt chẵn\" có 3 kết quả thuận lợi, \"mặt 6\" chỉ có 1, nên \"mặt chẵn\" lớn hơn."}]'::jsonb, '[{"de":"\"Mặt lớn hơn 1\" hay \"mặt chẵn\" khả năng lớn hơn?","dapAn":"\"Mặt lớn hơn 1\"","giaiThich":"5 kết quả so với 3."},{"de":"3 bi đỏ, 3 bi vàng: màu nào khả năng lớn hơn?","dapAn":"Như nhau","giaiThich":"Cùng 3 kết quả."}]'::jsonb),
  ('VBH-XS-03', 'Công thức 1/k chỉ đúng khi k biến cố đồng khả năng. Đếm theo "loại" là bẫy hay gặp.', 'Nếu có k biến cố đồng khả năng và luôn xảy ra đúng một trong số đó thì xác suất mỗi biến cố là 1/k. Đánh số từng viên bi, từng mặt, từng ô bằng nhau để có các kết quả đồng khả năng.', '[{"de":"1 bi đỏ, 3 bi xanh. Xác suất lấy được viên bi đỏ?","giai":"Cách nghĩ sai: \"đỏ hoặc xanh\" nên 1/2. Cách đúng: bốn viên bi đồng khả năng, viên đỏ là một trong bốn, xác suất 1/4."},{"de":"Vòng quay 8 ô bằng nhau, xác suất chỉ ô số 3?","giai":"8 ô đồng khả năng, xác suất 1/8."}]'::jsonb, '[{"de":"Xúc xắc cân đối, xác suất ra mặt 2?","dapAn":"1/6","giaiThich":"6 mặt đồng khả năng."},{"de":"Hộp 5 thẻ khác số, xác suất rút được thẻ số 4?","dapAn":"1/5","giaiThich":"5 thẻ đồng khả năng."}]'::jsonb),
  ('VBH-XS-04', 'Đồng xu, xúc xắc "không có trí nhớ". Các lần trước không làm thay đổi lần sau.', 'Mỗi lần gieo là độc lập: đồng xu cân đối ra ngửa với xác suất 1/2 ở mọi lần. Tỉ lệ thu được sau vài lần thử chỉ là kết quả thực tế, không phải xác suất.', '[{"de":"Đồng xu ra ngửa 3 lần liền. Lần thứ tư thì sao?","giai":"Cách nghĩ sai: chắc chắn ra sấp (hoặc chắc ra ngửa). Cách đúng: xác suất ra ngửa vẫn là 1/2."},{"de":"Gieo 10 lần được 7 lần ngửa. Xác suất ra ngửa là 7/10?","giai":"Không. Với đồng xu cân đối, xác suất là 1/2; 7/10 chỉ là kết quả của 10 lần gieo."}]'::jsonb, '[{"de":"Xúc xắc ra mặt 6 hai lần liền. Lần sau xác suất ra mặt 6?","dapAn":"1/6","giaiThich":"Không đổi."},{"de":"Kết quả lần trước có làm thay đổi xác suất lần sau không?","dapAn":"Không","giaiThich":"Các lần gieo độc lập."}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

