-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-GCD-01', 'C9-B31-M1', 'Xác định sai cạnh đối diện của một góc: lấy một cạnh kề (chứa đỉnh của góc) làm cạnh đối diện. Ví dụ: Trong tam giác ABC, cho rằng góc A đối diện với cạnh AB', 'VBH-GCD-01'),
  ('E-GCD-02', 'C9-B31-M1', 'So sánh ngược chiều: cho rằng góc lớn hơn đối diện cạnh nhỏ hơn, hoặc không nhận ra cạnh đối diện góc vuông, góc tù là cạnh lớn nhất. Ví dụ: AB > AC nên góc B > góc C', 'VBH-GCD-02'),
  ('E-DVX-01', 'C9-B32-M1', 'Nhầm đường vuông góc với đường xiên; lấy độ dài một đường xiên làm khoảng cách từ điểm đến đường thẳng. Ví dụ: Khoảng cách từ A đến d là độ dài AB với B là điểm bất kì trên d', 'VBH-DVX-01'),
  ('E-DVX-02', 'C9-B32-M2', 'Cho rằng có đường xiên ngắn hơn hoặc bằng đường vuông góc kẻ từ cùng một điểm. Ví dụ: AH ⊥ d, AH = 4 cm mà vẽ đường xiên AB = 3,5 cm', 'VBH-DVX-02'),
  ('E-BDT-01', 'C9-B33-M1', 'Kiểm tra bộ ba độ dài chỉ bằng một bất đẳng thức tuỳ ý (không dùng cạnh lớn nhất), hoặc chấp nhận tổng hai cạnh bằng cạnh thứ ba. Ví dụ: Cho rằng 2 cm, 3 cm, 5 cm là ba cạnh của tam giác', 'VBH-BDT-01'),
  ('E-BDT-02', 'C9-B33-M1', 'Tìm cạnh thứ ba chỉ dùng "nhỏ hơn tổng" mà quên "lớn hơn hiệu" (hoặc ngược lại), hoặc lấy cả hai đầu mút. Ví dụ: Hai cạnh 2 cm và 7 cm, cho cạnh thứ ba có thể là 5 cm', 'VBH-BDT-02'),
  ('E-TTU-01', 'C9-B34-M1', 'Nhầm đường trung tuyến với đường cao hoặc đường phân giác; nối đỉnh với một điểm bất kì của cạnh đối diện. Ví dụ: Vẽ trung tuyến AM bằng cách kẻ đường vuông góc từ A xuống BC', 'VBH-TTU-01'),
  ('E-TTU-02', 'C9-B34-M1B', 'Nhầm tỉ lệ trọng tâm chia đường trung tuyến: AG = 1/2 AM, GM = 2/3 AM, hoặc nhầm trọng tâm với giao điểm khác. Ví dụ: AM = 9 cm nên AG = 4,5 cm', 'VBH-TTU-02'),
  ('E-PGT-01', 'C9-B34-M2', 'Cho rằng đường phân giác của tam giác luôn đi qua trung điểm cạnh đối diện hoặc vuông góc với cạnh đó. Ví dụ: AD là phân giác nên BD = DC', 'VBH-PGT-01'),
  ('E-PGT-02', 'C9-B34-M2B', 'Cho rằng giao điểm ba đường phân giác cách đều ba đỉnh (nhầm với giao điểm ba đường trung trực), hoặc tính góc tại giao điểm sai. Ví dụ: I là giao điểm ba phân giác nên IA = IB = IC', 'VBH-PGT-02'),
  ('E-TTRT-01', 'C9-B35-M1', 'Cho rằng giao điểm ba đường trung trực cách đều ba cạnh, hoặc luôn nằm trong tam giác. Ví dụ: Tam giác tù cũng có giao điểm ba trung trực nằm trong tam giác', 'VBH-TTRT-01'),
