insert into error_hints (error_code, tier, hint_text) values
  ('E-GCD-01', 1, 'Cạnh em chọn có chứa đỉnh của góc đó không?'),
  ('E-GCD-01', 2, 'Cạnh đối diện với một góc là cạnh KHÔNG chứa đỉnh của góc đó. Góc A đối diện cạnh BC, góc B đối diện cạnh AC, góc C đối diện cạnh AB.'),
  ('E-GCD-01', 3, 'Ví dụ: tam giác MNP, góc P đối diện cạnh MN (cạnh không có chữ P).'),
  ('E-GCD-02', 1, 'Cạnh lớn hơn thì góc đối diện với nó lớn hơn hay nhỏ hơn?'),
  ('E-GCD-02', 2, 'Trong một tam giác: cạnh lớn hơn đối diện góc lớn hơn, góc lớn hơn đối diện cạnh lớn hơn. Tam giác vuông (tù): cạnh đối diện góc vuông (tù) là cạnh lớn nhất.'),
  ('E-GCD-02', 3, 'Ví dụ: AB > AC thì góc C (đối diện AB) > góc B (đối diện AC).'),
  ('E-DVX-01', 1, 'Đoạn thẳng này có vuông góc với d không?'),
  ('E-DVX-01', 2, 'Từ A ∉ d: AH ⊥ d (H ∈ d) là đường vuông góc, H là chân đường vuông góc; mọi đoạn AB khác (B ∈ d, B ≠ H) là đường xiên. Khoảng cách từ A đến d là độ dài AH.'),
  ('E-DVX-01', 3, 'Ví dụ: hình chữ nhật ABCD, khoảng cách từ A đến đường thẳng CD là AD (vì AD ⊥ CD).'),
  ('E-DVX-02', 1, 'Đường xiên AB là cạnh gì của tam giác vuông AHB?'),
  ('E-DVX-02', 2, 'Trong tam giác AHB vuông tại H, AB là cạnh huyền nên AB > AH. Vậy đường vuông góc ngắn hơn mọi đường xiên.'),
  ('E-DVX-02', 3, 'Ví dụ: AH = 5 cm thì mọi đường xiên kẻ từ A dài hơn 5 cm.'),
  ('E-BDT-01', 1, 'Em đã lấy hai cạnh nhỏ cộng lại rồi so với cạnh lớn nhất chưa? Tổng có lớn hơn hẳn không?'),
  ('E-BDT-01', 2, 'Ba độ dài là ba cạnh của tam giác khi tổng hai độ dài nhỏ LỚN HƠN độ dài lớn nhất. Nếu bằng nhau thì ba điểm thẳng hàng, không tạo thành tam giác.'),
  ('E-BDT-01', 3, 'Ví dụ: 2 + 3 = 5 nên 2 cm, 3 cm, 5 cm không là ba cạnh của tam giác; 2 + 3 = 5 > 4 nên 2, 3, 4 là ba cạnh.'),
  ('E-BDT-02', 1, 'Cạnh thứ ba phải lớn hơn số nào và nhỏ hơn số nào?'),
  ('E-BDT-02', 2, 'Với hai cạnh a và b (a ≥ b), cạnh thứ ba c thỏa mãn a − b < c < a + b (không lấy hai đầu mút).'),
  ('E-BDT-02', 3, 'Ví dụ: hai cạnh 7 cm và 2 cm thì 5 < c < 9; c có thể là 6, 7, 8 cm (nếu nguyên), không phải 5 hay 9.'),
  ('E-TTU-01', 1, 'Đầu kia của đoạn thẳng em vẽ có phải là trung điểm cạnh đối diện không?'),
  ('E-TTU-01', 2, 'Đường trung tuyến nối một đỉnh với TRUNG ĐIỂM cạnh đối diện. Nó khác đường cao (vuông góc) và đường phân giác (chia đôi góc). Mỗi tam giác có 3 đường trung tuyến.'),
  ('E-TTU-01', 3, 'Ví dụ: N là trung điểm AC thì BN là trung tuyến xuất phát từ B.'),
  ('E-TTU-02', 1, 'Trọng tâm cách đỉnh bao nhiêu phần của đường trung tuyến?'),
  ('E-TTU-02', 2, 'G chia trung tuyến AM theo tỉ lệ: AG = 2/3 AM, GM = 1/3 AM, AG = 2GM. Trọng tâm luôn nằm trong tam giác.'),
  ('E-TTU-02', 3, 'Ví dụ: AM = 9 cm ⇒ AG = 6 cm, GM = 3 cm.'),
  ('E-PGT-01', 1, 'Đường phân giác chia đôi cái gì: góc hay cạnh?'),
  ('E-PGT-01', 2, 'Đường phân giác AD chia góc A thành hai góc bằng nhau; D thường KHÔNG phải trung điểm BC và AD thường không vuông góc với BC (trừ khi tam giác cân tại A).'),
  ('E-PGT-01', 3, 'Ví dụ: góc A = 70° ⇒ góc BAD = góc DAC = 35°; còn BD, DC có thể khác nhau.'),
  ('E-PGT-02', 1, 'Điểm trên tia phân giác của một góc cách đều hai cạnh hay hai điểm?'),
  ('E-PGT-02', 2, 'Giao điểm I của ba đường phân giác cách đều BA CẠNH của tam giác (khoảng cách đo theo đường vuông góc). Điểm cách đều ba ĐỈNH là giao điểm ba đường trung trực.'),
  ('E-PGT-02', 3, 'Ví dụ: góc A = 80° ⇒ góc B + góc C = 100° ⇒ góc IBC + góc ICB = 50° ⇒ góc BIC = 130°.'),
  ('E-TTRT-01', 1, 'Điểm trên đường trung trực của một đoạn thẳng cách đều cái gì?'),
  ('E-TTRT-01', 2, 'Giao điểm O của ba đường trung trực cách đều BA ĐỈNH (OA = OB = OC). O nằm trong tam giác nhọn, ở trung điểm cạnh huyền của tam giác vuông, ở ngoài tam giác tù.'),
  ('E-TTRT-01', 3, 'Ví dụ: ba nhà ở A, B, C muốn giếng cách đều ba nhà thì đặt giếng tại O.'),
  ('E-DCAO-01', 1, 'Đường em vẽ có xuất phát từ đỉnh và vuông góc với đường thẳng chứa cạnh đối diện không?'),
  ('E-DCAO-01', 2, 'Đường cao từ A: đoạn vuông góc kẻ từ A đến ĐƯỜNG THẲNG BC. Với tam giác tù, chân đường cao từ đỉnh góc nhọn có thể nằm ngoài đoạn BC — cần kéo dài BC.'),
  ('E-DCAO-01', 3, 'Ví dụ: góc C tù, kéo dài BC về phía C rồi kẻ AH vuông góc với đường thẳng đó.'),
  ('E-DCAO-02', 1, 'Trực tâm là giao điểm của ba đường nào?'),
  ('E-DCAO-02', 2, 'Trực tâm là giao điểm ba đường cao. Tam giác vuông: trực tâm là đỉnh góc vuông. Tam giác tù: trực tâm nằm ngoài tam giác. Trọng tâm (giao ba trung tuyến) là điểm khác.'),
  ('E-DCAO-02', 3, 'Ví dụ: tam giác vuông tại A có hai cạnh góc vuông AB, AC cũng là hai đường cao, nên trực tâm là A.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-GCD-01', 'Mọi so sánh cạnh – góc đều bắt đầu từ việc chỉ đúng "cạnh đối diện". Chỉ sai ở đây thì cả bài sai.', 'Cạnh đối diện với một góc là cạnh không chứa đỉnh của góc đó: góc A ↔ cạnh BC, góc B ↔ cạnh AC, góc C ↔ cạnh AB.', '[{"de":"Trong tam giác ABC, góc A đối diện cạnh nào?","giai":"Cách nghĩ sai: AB (có chữ A). Cách đúng: cạnh không chứa A là BC."},{"de":"Tam giác MNP, góc nhỏ nhất đối diện cạnh MN = 5 cm (cạnh nhỏ nhất). Đó là góc nào?","giai":"Cạnh MN không chứa đỉnh P, nên góc đối diện là góc P."}]'::jsonb, '[{"de":"Góc B của tam giác ABC đối diện cạnh nào?","dapAn":"AC","giaiThich":"AC không chứa B."},{"de":"Cạnh EF của tam giác DEF đối diện góc nào?","dapAn":"Góc D","giaiThich":"EF không chứa D."}]'::jsonb),
  ('VBH-GCD-02', 'Quan hệ cạnh – góc luôn "cùng chiều": lớn đối diện lớn, nhỏ đối diện nhỏ.', 'Trong một tam giác, cạnh lớn hơn đối diện với góc lớn hơn và ngược lại. Trong tam giác vuông (hoặc tù), cạnh đối diện góc vuông (góc tù) là cạnh lớn nhất.', '[{"de":"Tam giác ABC có AB > AC. So sánh góc B và góc C.","giai":"Cách nghĩ sai: góc B > góc C (vì B đứng trong AB). Cách đúng: AB đối diện góc C, AC đối diện góc B; AB > AC nên góc C > góc B."},{"de":"Tam giác ABC có góc B = 50°, góc C = 70°. Sắp xếp các cạnh.","giai":"Góc A = 60°. Góc B < góc A < góc C nên AC < BC < AB."}]'::jsonb, '[{"de":"Tam giác vuông tại A, cạnh lớn nhất?","dapAn":"BC","giaiThich":"Đối diện góc vuông."},{"de":"Góc A = 30°, góc B = 70°. Cạnh nhỏ nhất?","dapAn":"BC","giaiThich":"Đối diện góc A nhỏ nhất."}]'::jsonb),
  ('VBH-DVX-01', 'Từ một điểm đến một đường thẳng có vô số đoạn thẳng, nhưng chỉ có một đường vuông góc.', 'Từ A ∉ d kẻ AH ⊥ d (H ∈ d): AH là đường vuông góc, H là chân đường vuông góc. Mọi đoạn AB với B ∈ d, B ≠ H là đường xiên. Khoảng cách từ A đến d là độ dài AH.', '[{"de":"Khoảng cách từ A đến d là độ dài AB với B bất kì trên d?","giai":"Cách nghĩ sai: đúng. Cách đúng: khoảng cách đo theo đường vuông góc, là AH."},{"de":"Hình chữ nhật ABCD có AB = 6 cm, BC = 4 cm. Khoảng cách từ A đến đường thẳng CD?","giai":"AD ⊥ CD nên khoảng cách là AD = BC = 4 cm."}]'::jsonb, '[{"de":"Từ A ngoài d kẻ được mấy đường vuông góc với d?","dapAn":"1","giaiThich":"Chỉ một."},{"de":"Tam giác vuông tại A: khoảng cách từ C đến đường thẳng AB?","dapAn":"CA","giaiThich":"CA ⊥ AB."}]'::jsonb),
  ('VBH-DVX-02', 'Đường vuông góc luôn "thắng" mọi đường xiên về độ ngắn.', 'Trong các đường vuông góc và đường xiên kẻ từ một điểm ở ngoài một đường thẳng đến đường thẳng đó, đường vuông góc là đường ngắn nhất. Lí do: đường xiên là cạnh huyền của tam giác vuông.', '[{"de":"AH = 4 cm. Có vẽ được đường xiên AB = 3,5 cm không?","giai":"Cách nghĩ sai: được, nếu B gần H. Cách đúng: tam giác AHB vuông tại H, AB là cạnh huyền nên AB > AH = 4 cm. Không vẽ được."},{"de":"Tam giác ABC có đường cao AH, H nằm giữa B và C. So sánh AH với AB, AC.","giai":"AB, AC là đường xiên nên AH < AB và AH < AC."}]'::jsonb, '[{"de":"AH = 5 cm, đường xiên AB có thể dài 6 cm không?","dapAn":"Có","giaiThich":"6 > 5."},{"de":"Tam giác vuông tại A: so sánh AB và BC.","dapAn":"AB < BC","giaiThich":"BC là cạnh huyền."}]'::jsonb),
  ('VBH-BDT-01', 'Không phải ba độ dài nào cũng ghép thành tam giác. Có một phép thử nhanh.', 'Ba độ dài là ba cạnh của một tam giác khi tổng hai độ dài nhỏ hơn LỚN HƠN độ dài lớn nhất. Nếu tổng bằng độ dài lớn nhất thì ba điểm thẳng hàng.', '[{"de":"2 cm, 3 cm, 5 cm có là ba cạnh của tam giác không?","giai":"Cách nghĩ sai: có, vì 3 + 5 > 2. Cách đúng: phải so hai cạnh nhỏ với cạnh lớn nhất: 2 + 3 = 5, không lớn hơn 5, nên không là tam giác."},{"de":"4 cm, 4 cm, 7 cm?","giai":"4 + 4 = 8 > 7 nên là ba cạnh của một tam giác (cân)."}]'::jsonb, '[{"de":"3, 4, 8 có là ba cạnh tam giác?","dapAn":"Không","giaiThich":"3 + 4 = 7 < 8."},{"de":"5, 6, 10 có là ba cạnh tam giác?","dapAn":"Có","giaiThich":"5 + 6 = 11 > 10."}]'::jsonb),
  ('VBH-BDT-02', 'Cạnh thứ ba của tam giác bị "kẹp" giữa hiệu và tổng hai cạnh kia.', 'Nếu hai cạnh là a và b (a ≥ b) thì cạnh thứ ba c thỏa mãn a − b < c < a + b. Không lấy hai đầu mút.', '[{"de":"Hai cạnh 2 cm và 7 cm, cạnh thứ ba có thể là 5 cm không?","giai":"Cách nghĩ sai: được, vì 5 < 9. Cách đúng: còn phải lớn hơn 7 − 2 = 5; 5 không lớn hơn 5 nên không được."},{"de":"AB = 1 cm, AC = 7 cm, BC nguyên. Tìm BC.","giai":"6 < BC < 8 nên BC = 7 cm."}]'::jsonb, '[{"de":"Hai cạnh 3 và 5, cạnh thứ ba nằm trong khoảng nào?","dapAn":"Từ 2 đến 8 (không kể 2 và 8)","giaiThich":"5 − 3 < c < 5 + 3."},{"de":"Tam giác cân có cạnh 3 cm và 7 cm, cạnh bên dài?","dapAn":"7 cm","giaiThich":"3 + 3 < 7 nên cạnh bên không thể là 3."}]'::jsonb),
  ('VBH-TTU-01', 'Trung tuyến, đường cao, phân giác đều xuất phát từ đỉnh, nên rất dễ lẫn. Trung tuyến gắn với một từ khóa: trung điểm.', 'Đường trung tuyến nối một đỉnh với TRUNG ĐIỂM của cạnh đối diện. Mỗi tam giác có ba đường trung tuyến.', '[{"de":"Vẽ trung tuyến AM bằng cách kẻ từ A đường vuông góc xuống BC có đúng không?","giai":"Cách nghĩ sai: đúng. Cách đúng: đó là đường cao; trung tuyến phải đi qua trung điểm M của BC (hai đường chỉ trùng nhau khi tam giác cân tại A)."},{"de":"BC = 8 cm, AM là trung tuyến. Tính BM.","giai":"M là trung điểm BC nên BM = 4 cm."}]'::jsonb, '[{"de":"N là trung điểm AC. BN là đường gì?","dapAn":"Trung tuyến từ B","giaiThich":"Nối B với trung điểm cạnh đối diện."},{"de":"Tam giác có mấy trung tuyến?","dapAn":"3","giaiThich":"Mỗi đỉnh một trung tuyến."}]'::jsonb),
  ('VBH-TTU-02', 'Trọng tâm không nằm ở giữa trung tuyến, mà ở vị trí 2/3 tính từ đỉnh.', 'G là trọng tâm, AM là trung tuyến: AG = 2/3 AM; GM = 1/3 AM; AG = 2GM. Trọng tâm luôn nằm bên trong tam giác.', '[{"de":"AM = 9 cm. Tính AG.","giai":"Cách nghĩ sai: AG = 9 : 2 = 4,5 cm. Cách đúng: AG = 2/3 · 9 = 6 cm."},{"de":"GM = 2 cm. Tính AM.","giai":"GM = 1/3 AM nên AM = 6 cm."}]'::jsonb, '[{"de":"AM = 12 cm. GM = ?","dapAn":"4 cm","giaiThich":"1/3 của 12."},{"de":"AG = 8 cm. AM = ?","dapAn":"12 cm","giaiThich":"AG = 2/3 AM."}]'::jsonb),
  ('VBH-PGT-01', 'Phân giác chia đôi GÓC, không chia đôi cạnh. Đây là chỗ hay nhầm với trung tuyến.', 'Đường phân giác AD (D ∈ BC) chia góc A thành hai góc bằng nhau. Nói chung D không phải trung điểm BC và AD không vuông góc với BC. Chỉ khi tam giác cân tại A thì phân giác, trung tuyến, đường cao từ A trùng nhau.', '[{"de":"AD là phân giác. Có chắc BD = DC không?","giai":"Cách nghĩ sai: chắc chắn. Cách đúng: không, chỉ chắc góc BAD = góc DAC."},{"de":"Góc A = 70°, AD là phân giác. Tính góc BAD.","giai":"70° : 2 = 35°."}]'::jsonb, '[{"de":"Góc A = 90°, phân giác AD. Góc DAC = ?","dapAn":"45°","giaiThich":"Chia đôi góc A."},{"de":"Tam giác cân tại A, phân giác AD có vuông góc với BC không?","dapAn":"Có","giaiThich":"Tam giác cân tại A."}]'::jsonb),
  ('VBH-PGT-02', 'Giao điểm ba đường phân giác có một tính chất đặc biệt: cách đều ba cạnh, không phải ba đỉnh.', 'Ba đường phân giác cùng đi qua điểm I; I cách đều ba cạnh (khoảng cách đo bằng đường vuông góc). Góc BIC = 180° − (góc B + góc C) : 2.', '[{"de":"I là giao điểm ba phân giác. IA = IB = IC đúng không?","giai":"Cách nghĩ sai: đúng. Cách đúng: I cách đều ba CẠNH; điểm cách đều ba ĐỈNH là giao điểm ba trung trực."},{"de":"Góc A = 80°, tính góc BIC.","giai":"Góc B + góc C = 100°; góc IBC + góc ICB = 50°; góc BIC = 130°."}]'::jsonb, '[{"de":"Khoảng cách từ I đến AB là 2 cm. Đến AC?","dapAn":"2 cm","giaiThich":"Cách đều ba cạnh."},{"de":"Trạm cách đều ba con đường bao quanh khu đất tam giác đặt ở đâu?","dapAn":"Giao điểm ba phân giác","giaiThich":"Cách đều ba cạnh."}]'::jsonb),
  ('VBH-TTRT-01', 'Giao điểm ba đường trung trực cách đều ba đỉnh, và không phải lúc nào cũng nằm trong tam giác.', 'Ba đường trung trực cùng đi qua O với OA = OB = OC. Vị trí O: trong tam giác nhọn; trung điểm cạnh huyền của tam giác vuông; ngoài tam giác tù.', '[{"de":"Giao điểm ba trung trực cách đều ba cạnh?","giai":"Cách nghĩ sai: đúng. Cách đúng: O cách đều ba đỉnh (vì mỗi điểm trên trung trực cách đều hai mút)."},{"de":"Tam giác vuông tại A, giao điểm ba trung trực nằm ở đâu?","giai":"Ở trung điểm cạnh huyền BC."}]'::jsonb, '[{"de":"OA = 5 cm, OB = ?","dapAn":"5 cm","giaiThich":"Cách đều ba đỉnh."},{"de":"Tam giác tù, O nằm ở đâu?","dapAn":"Ngoài tam giác","giaiThich":"Vị trí phụ thuộc loại tam giác."}]'::jsonb),
  ('VBH-DCAO-01', 'Đường cao luôn vẽ được, kể cả trong tam giác tù — chỉ cần kéo dài cạnh.', 'Đường cao từ A là đoạn vuông góc kẻ từ A đến ĐƯỜNG THẲNG BC. Nếu tam giác tù, chân đường cao kẻ từ đỉnh góc nhọn có thể nằm ngoài đoạn BC: kéo dài BC rồi kẻ vuông góc.', '[{"de":"Góc C tù thì có vẽ được đường cao từ A không?","giai":"Cách nghĩ sai: không, vì chân đường vuông góc không nằm trên cạnh BC. Cách đúng: kéo dài BC về phía C, kẻ AH vuông góc với đường thẳng BC; H nằm trên tia đối của tia CB."},{"de":"Tam giác vuông tại A, đường cao từ B là gì?","giai":"BA (vì BA ⊥ AC)."}]'::jsonb, '[{"de":"Đường cao từ A phải vuông góc với?","dapAn":"Đường thẳng BC","giaiThich":"Đường thẳng chứa cạnh đối diện."},{"de":"Tam giác có mấy đường cao?","dapAn":"3","giaiThich":"Mỗi đỉnh một đường cao."}]'::jsonb),
  ('VBH-DCAO-02', 'Bốn điểm đặc biệt của tam giác có bốn tên gọi riêng. Trực tâm là giao điểm của ba đường cao.', 'Trực tâm H là giao điểm ba đường cao. Tam giác nhọn: H ở trong; tam giác vuông: H là đỉnh góc vuông; tam giác tù: H ở ngoài. Trọng tâm (ba trung tuyến) là điểm khác, luôn ở trong.', '[{"de":"Tam giác vuông tại A, trực tâm là trung điểm BC?","giai":"Cách nghĩ sai: đúng. Cách đúng: AB và AC đã là hai đường cao (vuông góc với nhau tại A), nên trực tâm là A."},{"de":"Tam giác đều có các điểm đặc biệt thế nào?","giai":"Trọng tâm, trực tâm, giao điểm ba phân giác, giao điểm ba trung trực trùng nhau."}]'::jsonb, '[{"de":"Tam giác tù có trực tâm nằm ở đâu?","dapAn":"Ngoài tam giác","giaiThich":"Hai đường cao nằm ngoài."},{"de":"Giao điểm ba đường trung tuyến gọi là?","dapAn":"Trọng tâm","giaiThich":"Không phải trực tâm."}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

