-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-HHCN-01', 'C10-B36-M1', 'Đếm sai số mặt, cạnh, đỉnh của hình hộp chữ nhật; nhầm đường chéo của một mặt với đường chéo của hình hộp. Ví dụ: Hình hộp chữ nhật có 8 cạnh; AC là đường chéo của hình hộp ABCD.A''B''C''D''', 'VBH-HHCN-01'),
  ('E-HHCN-02', 'C10-B36-M1', 'Không nhận ra các cạnh song song bằng nhau (mỗi kích thước có 4 cạnh) và các mặt đối diện bằng nhau. Ví dụ: Tổng các cạnh của hình hộp 3 × 4 × 5 cm là 3 + 4 + 5 = 12 cm', 'VBH-HHCN-02'),
  ('E-LPH-01', 'C10-B36-M1B', 'Không nắm hình lập phương có 6 mặt là hình vuông bằng nhau, 12 cạnh bằng nhau; cho rằng hình lập phương không phải là hình hộp chữ nhật. Ví dụ: Hình lập phương không phải là hình hộp chữ nhật', 'VBH-LPH-01'),
  ('E-SXQ-01', 'C10-B36-M2', 'Tính diện tích xung quanh hình hộp chữ nhật sai: cộng cả hai đáy (diện tích toàn phần), nhân ba kích thước, hoặc quên nhân 2. Ví dụ: Hộp 5 × 3 × 4 cm có Sxq = 94 cm²', 'VBH-SXQ-01'),
  ('E-THT-01', 'C10-B36-M2', 'Tính thể tích bằng công thức diện tích (cộng hoặc nhân hai kích thước), viết đơn vị cm² cho thể tích, hoặc tìm kích thước khi biết thể tích sai. Ví dụ: Hộp 5 × 3 × 4 cm có thể tích 60 cm²', 'VBH-THT-01'),
  ('E-DVI-01', 'C10-B36-M2', 'Đổi đơn vị thể tích sai: coi 1 m³ = 100 dm³ hoặc 1 m³ = 100 lít; quên 1 dm³ = 1 lít. Ví dụ: Bể 3 m³ chứa được 300 lít nước', 'VBH-DVI-01'),
  ('E-LPH-02', 'C10-B36-M2B', 'Tính diện tích xung quanh hình lập phương bằng 6a² hoặc 4a, thể tích bằng 3a hoặc a²; tìm cạnh từ thể tích bằng cách chia 3. Ví dụ: Lập phương cạnh 3 cm có thể tích 9 cm³', 'VBH-LPH-02'),
  ('E-LTR-01', 'C10-B37-M1', 'Đếm sai mặt, cạnh, đỉnh của lăng trụ đứng; nhầm mặt đáy với mặt bên; cho rằng mặt bên là tam giác hoặc chiều cao lăng trụ khác cạnh bên. Ví dụ: Lăng trụ đứng tam giác có 3 mặt; mặt bên là hình tam giác', 'VBH-LTR-01'),
  ('E-LTR-02', 'C10-B37-M1B', 'Vẽ hoặc nhận hình khai triển sai: số mặt bên không bằng số cạnh đáy, hai đáy cùng một phía, các mặt bên có chiều cao khác nhau. Ví dụ: Hình khai triển lăng trụ tam giác gồm 3 tam giác và 2 hình chữ nhật', 'VBH-LTR-02'),
  ('E-SXQL-01', 'C10-B37-M2', 'Tính diện tích xung quanh lăng trụ đứng bằng diện tích đáy nhân chiều cao, cộng thêm hai đáy, hoặc dùng chiều cao của tam giác đáy thay chiều cao lăng trụ. Ví dụ: Đáy tam giác 3–4–5 cm, cao 5 cm: Sxq = 6 · 5 = 30 cm²', 'VBH-SXQL-01'),
  ('E-VLT-01', 'C10-B37-M2B', 'Tính thể tích lăng trụ đứng bằng chu vi đáy nhân chiều cao, hoặc tính diện tích đáy tam giác quên chia 2. Ví dụ: Đáy tam giác vuông 3 cm và 4 cm, cao 10 cm: V = 3 · 4 · 10 = 120 cm³', 'VBH-VLT-01')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
