insert into error_hints (error_code, tier, hint_text) values
  ('E-HHCN-01', 1, 'Em đếm lại: mặt đáy dưới có mấy cạnh, mặt đáy trên có mấy cạnh, có mấy cạnh bên?'),
  ('E-HHCN-01', 2, 'Hình hộp chữ nhật (và hình lập phương) có 6 mặt, 12 cạnh (4 cạnh đáy dưới + 4 cạnh đáy trên + 4 cạnh bên), 8 đỉnh, 4 đường chéo. Đường chéo của hình hộp nối hai đỉnh không cùng nằm trên một mặt (như AC''), khác đường chéo của một mặt (như AC).'),
  ('E-HHCN-01', 3, 'Ví dụ: ABCD.A''B''C''D'' có 4 đường chéo AC'', BD'', CA'', DB''.'),
  ('E-HHCN-02', 1, 'Cạnh này song song với cạnh nào? Các cạnh song song có bằng nhau không?'),
  ('E-HHCN-02', 2, 'Hình hộp chữ nhật có ba kích thước; mỗi kích thước ứng với 4 cạnh bằng nhau. Hai mặt đối diện song song và bằng nhau.'),
  ('E-HHCN-02', 3, 'Ví dụ: hình hộp 3 × 4 × 5 cm có tổng các cạnh 4 · (3 + 4 + 5) = 48 cm.'),
  ('E-LPH-01', 1, 'Các mặt của hình lập phương là hình gì? Các cạnh có bằng nhau không?'),
  ('E-LPH-01', 2, 'Hình lập phương có 6 mặt là hình vuông bằng nhau, 12 cạnh bằng nhau. Hình lập phương là hình hộp chữ nhật đặc biệt có ba kích thước bằng nhau.'),
  ('E-LPH-01', 3, 'Ví dụ: lập phương cạnh 5 cm có 12 cạnh đều 5 cm, tổng các cạnh 60 cm.'),
  ('E-SXQ-01', 1, 'Diện tích xung quanh gồm những mặt nào? Có tính hai đáy không?'),
  ('E-SXQ-01', 2, 'Diện tích xung quanh là tổng diện tích bốn mặt bên: Sxq = 2(a + b) · c (chu vi đáy × chiều cao). Diện tích toàn phần mới cộng thêm hai đáy.'),
  ('E-SXQ-01', 3, 'Ví dụ: hộp 5 × 3 × 4 cm: Sxq = 2 · (5 + 3) · 4 = 64 cm²; Stp = 64 + 2 · 15 = 94 cm².'),
  ('E-THT-01', 1, 'Thể tích đo bằng đơn vị gì: cm² hay cm³?'),
  ('E-THT-01', 2, 'Thể tích hình hộp chữ nhật V = a · b · c (diện tích đáy × chiều cao), đơn vị khối (cm³, dm³, m³). Muốn tìm chiều cao: lấy thể tích chia cho diện tích đáy.'),
  ('E-THT-01', 3, 'Ví dụ: hộp 5 × 3 × 4 cm có V = 60 cm³. Đáy 6 × 4 cm, V = 120 cm³ thì cao 120 : 24 = 5 cm.'),
  ('E-DVI-01', 1, '1 m³ bằng bao nhiêu dm³? 1 dm³ bằng bao nhiêu lít?'),
  ('E-DVI-01', 2, 'Mỗi đơn vị thể tích gấp 1 000 lần đơn vị nhỏ hơn liền sau: 1 m³ = 1 000 dm³ = 1 000 000 cm³. 1 dm³ = 1 lít.'),
  ('E-DVI-01', 3, 'Ví dụ: bể 3 m³ = 3 000 dm³ = 3 000 lít.'),
  ('E-LPH-02', 1, 'Hình lập phương có mấy mặt bên? Thể tích là a nhân a nhân a hay a nhân 3?'),
  ('E-LPH-02', 2, 'Hình lập phương cạnh a: Sxq = 4a² (4 mặt bên), Stp = 6a², V = a³ = a · a · a.'),
  ('E-LPH-02', 3, 'Ví dụ: cạnh 3 cm: V = 27 cm³; Sxq = 36 cm². V = 64 cm³ thì a = 4 cm (vì 4 · 4 · 4 = 64).'),
  ('E-LTR-01', 1, 'Hai đáy của lăng trụ là hai hình nào song song với nhau? Các mặt còn lại là hình gì?'),
  ('E-LTR-01', 2, 'Lăng trụ đứng có hai đáy song song và bằng nhau (tam giác hoặc tứ giác), các mặt bên là hình chữ nhật, các cạnh bên bằng nhau và bằng chiều cao. Lăng trụ đứng tam giác: 5 mặt, 9 cạnh, 6 đỉnh.'),
  ('E-LTR-01', 3, 'Ví dụ: ABC.A''B''C'' có đáy ABC, A''B''C''; mặt bên ABB''A'', BCC''B'', CAA''C''; chiều cao AA''.'),
  ('E-LTR-02', 1, 'Số hình chữ nhật mặt bên có bằng số cạnh của đáy không? Hai đáy đặt ở đâu?'),
  ('E-LTR-02', 2, 'Hình khai triển lăng trụ đứng: một dải các hình chữ nhật cùng chiều cao (số hình bằng số cạnh đáy, mỗi hình có một cạnh bằng một cạnh đáy) và hai đáy bằng nhau gắn ở hai phía của dải.'),
  ('E-LTR-02', 3, 'Ví dụ: đáy tam giác 3–4–5 cm, cao 6 cm: dải ba hình chữ nhật 3 × 6, 4 × 6, 5 × 6 cm và hai tam giác.'),
  ('E-SXQL-01', 1, 'Em dùng chu vi đáy hay diện tích đáy? Chiều cao em dùng là chiều cao của lăng trụ hay của tam giác đáy?'),
  ('E-SXQL-01', 2, 'Sxq lăng trụ đứng = chu vi đáy × chiều cao lăng trụ (chiều cao lăng trụ là độ dài cạnh bên). Không cộng hai đáy, không dùng diện tích đáy.'),
  ('E-SXQL-01', 3, 'Ví dụ: đáy 3–4–5 cm, cao 8 cm: Sxq = (3 + 4 + 5) · 8 = 96 cm².'),
  ('E-VLT-01', 1, 'Diện tích đáy tam giác tính bằng công thức nào? Em đã chia 2 chưa?'),
  ('E-VLT-01', 2, 'Thể tích lăng trụ đứng V = diện tích đáy × chiều cao. Đáy tam giác: S = cạnh × chiều cao ứng với cạnh đó : 2. Đáy hình thang: S = (đáy lớn + đáy nhỏ) × chiều cao : 2.'),
  ('E-VLT-01', 3, 'Ví dụ: đáy tam giác vuông 3 cm, 4 cm: S = 3 · 4 : 2 = 6 cm²; cao 10 cm thì V = 60 cm³.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-HHCN-01', 'Hình hộp chữ nhật rất quen (hộp sữa, viên gạch), nhưng đếm cạnh, đỉnh, đường chéo vẫn hay sai.', 'Hình hộp chữ nhật có 6 mặt, 12 cạnh (4 cạnh đáy dưới, 4 cạnh đáy trên, 4 cạnh bên), 8 đỉnh và 4 đường chéo. Đường chéo của hình hộp nối hai đỉnh không cùng nằm trên một mặt.', '[{"de":"Trong ABCD.A''B''C''D'', AC có phải đường chéo của hình hộp không?","giai":"Cách nghĩ sai: có. Cách đúng: A và C cùng nằm trên mặt ABCD nên AC là đường chéo của mặt đáy. Đường chéo của hình hộp là AC'', BD'', CA'', DB''."},{"de":"Hình hộp chữ nhật có mấy cạnh?","giai":"4 + 4 + 4 = 12 cạnh."}]'::jsonb, '[{"de":"Hình hộp chữ nhật có mấy đỉnh?","dapAn":"8","giaiThich":"4 đỉnh dưới, 4 đỉnh trên."},{"de":"Hình hộp có mấy đường chéo?","dapAn":"4","giaiThich":"AC'', BD'', CA'', DB''."}]'::jsonb),
  ('VBH-HHCN-02', 'Hình hộp chữ nhật chỉ có ba kích thước, nhưng mỗi kích thước xuất hiện ở bốn cạnh.', 'Mỗi kích thước (dài, rộng, cao) ứng với 4 cạnh song song và bằng nhau. Hai mặt đối diện song song và bằng nhau. Tổng độ dài các cạnh = 4 · (a + b + c).', '[{"de":"Tổng các cạnh của hình hộp 3 × 4 × 5 cm?","giai":"Cách nghĩ sai: 3 + 4 + 5 = 12 cm. Cách đúng: mỗi kích thước có 4 cạnh, tổng 4 · 12 = 48 cm."},{"de":"AB = 5 cm. Những cạnh nào cũng bằng 5 cm?","giai":"Các cạnh song song với AB: CD, A''B'', C''D''."}]'::jsonb, '[{"de":"Mặt đối diện với ABCD?","dapAn":"A''B''C''D''","giaiThich":"Hai đáy."},{"de":"Hình hộp 2 × 3 × 4 cm, tổng các cạnh?","dapAn":"36 cm","giaiThich":"4 · 9."}]'::jsonb),
  ('VBH-LPH-01', 'Hình lập phương là một hình hộp chữ nhật "đặc biệt": mọi kích thước đều bằng nhau.', 'Hình lập phương có 6 mặt là hình vuông bằng nhau, 12 cạnh bằng nhau, 8 đỉnh, 4 đường chéo. Nó là hình hộp chữ nhật có ba kích thước bằng nhau.', '[{"de":"Hình lập phương có phải hình hộp chữ nhật không?","giai":"Cách nghĩ sai: không, vì các mặt là hình vuông. Cách đúng: hình vuông cũng là hình chữ nhật, nên hình lập phương là hình hộp chữ nhật có ba kích thước bằng nhau."},{"de":"Tổng các cạnh của hình lập phương cạnh 5 cm?","giai":"12 cạnh bằng nhau: 12 · 5 = 60 cm."}]'::jsonb, '[{"de":"Mặt của hình lập phương là hình gì?","dapAn":"Hình vuông","giaiThich":"6 hình vuông bằng nhau."},{"de":"Tổng các cạnh 36 cm, cạnh dài?","dapAn":"3 cm","giaiThich":"36 : 12."}]'::jsonb),
  ('VBH-SXQ-01', 'Diện tích xung quanh chỉ là "vòng quanh", không có nắp và đáy.', 'Sxq hình hộp chữ nhật = tổng diện tích 4 mặt bên = 2(a + b) · c = chu vi đáy × chiều cao. Diện tích toàn phần Stp = Sxq + 2 · diện tích đáy.', '[{"de":"Hộp 5 × 3 × 4 cm, tính Sxq.","giai":"Cách nghĩ sai: 94 cm² (đã cộng hai đáy) hoặc 60 (nhân ba kích thước). Cách đúng: 2 · (5 + 3) · 4 = 64 cm²."},{"de":"Sơn bốn bức tường phòng 5 × 4 × 3 m, trừ cửa 6 m².","giai":"Sxq = 2 · 9 · 3 = 54 m²; cần sơn 54 − 6 = 48 m²."}]'::jsonb, '[{"de":"Hộp 2 × 2 × 5 cm, Sxq?","dapAn":"40 cm²","giaiThich":"2 · 4 · 5."},{"de":"Hộp 4 × 3 × 2 cm, Stp?","dapAn":"52 cm²","giaiThich":"Sxq 28 + 2 · 12."}]'::jsonb),
  ('VBH-THT-01', 'Thể tích đo "sức chứa" trong không gian ba chiều, nên phải nhân đủ ba kích thước và dùng đơn vị khối.', 'V hình hộp chữ nhật = a · b · c = diện tích đáy × chiều cao; đơn vị cm³, dm³, m³. Tìm chiều cao: h = V : diện tích đáy.', '[{"de":"Hộp 5 × 3 × 4 cm có thể tích bao nhiêu?","giai":"Cách nghĩ sai: 60 cm² (đơn vị diện tích) hoặc 12 (cộng). Cách đúng: 5 · 3 · 4 = 60 cm³."},{"de":"V = 120 cm³, đáy 6 × 4 cm. Tìm chiều cao.","giai":"Diện tích đáy 24 cm²; h = 120 : 24 = 5 cm."}]'::jsonb, '[{"de":"Hộp 2 × 3 × 4 cm, thể tích?","dapAn":"24 cm³","giaiThich":"Nhân ba kích thước."},{"de":"V = 60 cm³, đáy 12 cm², chiều cao?","dapAn":"5 cm","giaiThich":"60 : 12."}]'::jsonb),
  ('VBH-DVI-01', 'Đơn vị thể tích "gấp 1 000", không phải "gấp 10" hay "gấp 100".', '1 m³ = 1 000 dm³; 1 dm³ = 1 000 cm³; 1 dm³ = 1 lít; nên 1 m³ = 1 000 lít.', '[{"de":"Bể 3 m³ chứa bao nhiêu lít?","giai":"Cách nghĩ sai: 300 lít. Cách đúng: 3 m³ = 3 000 dm³ = 3 000 lít."},{"de":"Thùng lập phương cạnh 1 m chứa bao nhiêu lít?","giai":"V = 1 m³ = 1 000 lít."}]'::jsonb, '[{"de":"2 dm³ bằng mấy lít?","dapAn":"2 lít","giaiThich":"1 dm³ = 1 lít."},{"de":"0,5 m³ bằng mấy lít?","dapAn":"500 lít","giaiThich":"0,5 · 1 000."}]'::jsonb),
  ('VBH-LPH-02', 'Với hình lập phương mọi cạnh bằng a, công thức gọn hơn — nhưng dễ nhầm 4a² với 6a², a³ với 3a.', 'Hình lập phương cạnh a: Sxq = 4a² (bốn mặt bên); Stp = 6a²; V = a³ = a · a · a.', '[{"de":"Lập phương cạnh 3 cm có thể tích bao nhiêu?","giai":"Cách nghĩ sai: 3 · 3 = 9 hoặc 3 · 3 = 9 cm³. Cách đúng: 3 · 3 · 3 = 27 cm³."},{"de":"V = 64 cm³, tìm cạnh.","giai":"Tìm số a mà a · a · a = 64: a = 4 cm."}]'::jsonb, '[{"de":"Cạnh 5 cm, Sxq?","dapAn":"100 cm²","giaiThich":"4 · 25."},{"de":"Cạnh tăng 2 lần, thể tích tăng?","dapAn":"8 lần","giaiThich":"2 · 2 · 2."}]'::jsonb),
  ('VBH-LTR-01', 'Lăng trụ đứng có "đáy" không nhất thiết nằm dưới đất. Đáy là hai mặt song song và bằng nhau.', 'Hình lăng trụ đứng tam giác (tứ giác) có hai đáy là tam giác (tứ giác) bằng nhau, song song; các mặt bên là hình chữ nhật; các cạnh bên bằng nhau và bằng chiều cao. Lăng trụ tam giác: 5 mặt, 9 cạnh, 6 đỉnh; lăng trụ tứ giác: 6 mặt, 12 cạnh, 8 đỉnh.', '[{"de":"Chiếc lều lăng trụ tam giác đặt trên mặt đất. Mặt đất dưới lều là mặt đáy?","giai":"Cách nghĩ sai: đúng, vì nằm dưới. Cách đúng: hai đáy là hai tam giác ở hai đầu lều; mặt hình chữ nhật trên đất là một mặt bên."},{"de":"Lăng trụ đứng tam giác có mấy cạnh?","giai":"3 cạnh đáy dưới + 3 cạnh đáy trên + 3 cạnh bên = 9 cạnh."}]'::jsonb, '[{"de":"Mặt bên của lăng trụ đứng là hình gì?","dapAn":"Hình chữ nhật","giaiThich":"Không phải tam giác."},{"de":"Lăng trụ đứng tứ giác có mấy mặt bên?","dapAn":"4","giaiThich":"Bằng số cạnh đáy."}]'::jsonb),
  ('VBH-LTR-02', 'Hình khai triển giúp tạo lập lăng trụ. Chỉ cần sai vị trí một đáy là không gấp được.', 'Hình khai triển lăng trụ đứng: một dải hình chữ nhật (số hình bằng số cạnh đáy, cùng chiều cao, mỗi hình có một cạnh bằng một cạnh đáy) và hai đáy bằng nhau gắn ở hai phía của dải.', '[{"de":"Hình khai triển lăng trụ tam giác gồm 3 tam giác và 2 hình chữ nhật?","giai":"Cách nghĩ sai: đúng. Cách đúng: chỉ có 2 tam giác (hai đáy) và 3 hình chữ nhật (ba mặt bên)."},{"de":"Đáy tam giác 3–4–5 cm, cao 6 cm. Ba mặt bên có kích thước?","giai":"3 × 6, 4 × 6 và 5 × 6 cm."}]'::jsonb, '[{"de":"Lăng trụ tứ giác cần mấy hình chữ nhật mặt bên?","dapAn":"4","giaiThich":"Bằng số cạnh đáy."},{"de":"Các mặt bên có cùng chiều cao không?","dapAn":"Có","giaiThich":"Bằng chiều cao lăng trụ."}]'::jsonb),
  ('VBH-SXQL-01', 'Diện tích xung quanh lăng trụ đứng giống như dải băng quấn quanh: dài bằng chu vi đáy, rộng bằng chiều cao.', 'Sxq lăng trụ đứng = chu vi đáy × chiều cao (chiều cao là độ dài cạnh bên). Không dùng diện tích đáy, không cộng hai đáy (trừ khi tính diện tích toàn phần).', '[{"de":"Đáy tam giác 3–4–5 cm, cao 5 cm. Tính Sxq.","giai":"Cách nghĩ sai: (3 · 4 : 2) · 5 = 30 cm² (dùng diện tích đáy). Cách đúng: (3 + 4 + 5) · 5 = 60 cm²."},{"de":"Sxq = 180 cm², chu vi đáy 15 cm. Tìm chiều cao.","giai":"h = 180 : 15 = 12 cm."}]'::jsonb, '[{"de":"Đáy vuông cạnh 3 cm, cao 5 cm, Sxq?","dapAn":"60 cm²","giaiThich":"12 · 5."},{"de":"Đáy tam giác đều cạnh 2 cm, cao 10 cm, Sxq?","dapAn":"60 cm²","giaiThich":"6 · 10."}]'::jsonb),
  ('VBH-VLT-01', 'Thể tích lăng trụ đứng = diện tích đáy × chiều cao. Hay sai nhất ở bước tính diện tích đáy tam giác.', 'V = S đáy × h. Đáy tam giác: S = cạnh đáy × chiều cao tương ứng : 2. Đáy hình thang: S = (đáy lớn + đáy nhỏ) × chiều cao : 2.', '[{"de":"Đáy tam giác vuông 3 cm và 4 cm, cao 10 cm. Tính V.","giai":"Cách nghĩ sai: 3 · 4 · 10 = 120 cm³ (quên chia 2). Cách đúng: S đáy = 3 · 4 : 2 = 6 cm²; V = 6 · 10 = 60 cm³."},{"de":"Đáy hình thang hai đáy 4 và 6 cm, cao hình thang 3 cm; lăng trụ cao 10 cm.","giai":"S đáy = (4 + 6) · 3 : 2 = 15 cm²; V = 150 cm³."}]'::jsonb, '[{"de":"S đáy 12 cm², h = 5 cm, V?","dapAn":"60 cm³","giaiThich":"12 · 5."},{"de":"V = 90 cm³, S đáy 15 cm², h?","dapAn":"6 cm","giaiThich":"90 : 15."}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

-- ===========================================================================
-- NGÂN HÀNG HOẠT ĐỘNG CHƯƠNG VI – X (bản nháp; giữ nguyên nếu giáo viên đã sửa)
-- ===========================================================================
insert into mm_activities
  (activity_id, ten, error_codes, nhom, hinh_thuc, muc_nhan_thuc, phut_min, phut_max, mo_ta, hoc_lieu, trang_thai, nguon)
values
  ('HD-TLT-01', 'Ghép cặp tỉ số bằng nhau', array['E-TLT-01', 'E-TLT-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 7, 10, 'Nhóm nhận 12 thẻ tỉ số (2/3, 8/12, 4/5, 1,5/2,25…). Ghép các cặp bằng nhau thành tỉ lệ thức, khoanh đỏ ngoại tỉ, khoanh xanh trung tỉ. Cặp nào không ghép được thì giải thích vì sao.', 'Bộ 12 thẻ tỉ số, bút hai màu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TLT-02', 'Nhân chéo và bốn tỉ lệ thức', array['E-TLT-03', 'E-TLT-04']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Mỗi nhóm nhận một đẳng thức tích (2 · 6 = 3 · 4, 5 · 8 = 4 · 10…), lập đủ 4 tỉ lệ thức và kiểm tra bằng nhân chéo. Sau đó giải 3 bài "tìm x" và đổi chéo bài để chấm.', 'Phiếu 4 ô tỉ lệ thức, 3 bài tìm x', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DTS-01', 'Đọc đề – viết dãy tỉ số', array['E-DTS-01', 'E-DTS-04']::text[], array['loi']::text[], 'ca-lop', 2, 6, 8, 'Giáo viên chiếu 6 câu "… tỉ lệ với …". Học sinh viết dãy tỉ số lên bảng con, giơ lên cùng lúc. Sau mỗi câu, một em đọc to: "đại lượng ở tử, số cho trước ở mẫu, đúng thứ tự".', 'Bảng con, 6 câu đề', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DTS-02', 'Tử nào mẫu nấy', array['E-DTS-02', 'E-DTS-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm sửa 4 lời giải có lỗi (cộng tử trừ mẫu; quên nhân hệ số 2x…), viết lại lời giải đúng và ghi một câu "luật" rút ra. Nhóm nhanh làm thêm bài có 2x + 3y.', '4 lời giải mẫu có lỗi', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TLTH-01', 'Thuận hay nghịch? Kiểm tra bằng bảng', array['E-TLTH-01', 'E-TLN-01']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 7, 10, 'Nhóm nhận 6 bảng giá trị (y = 3x; y = x + 3; xy = 12; y = 10 − x…). Thêm một hàng tính y/x và một hàng tính xy, rồi kết luận tỉ lệ thuận, tỉ lệ nghịch hay không tỉ lệ.', '6 bảng giá trị có thêm hai hàng trống', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TLTH-02', 'Hệ số hai chiều', array['E-TLTH-02', 'E-TLTH-03']::text[], array['loi']::text[], 'ca-nhan', 2, 5, 8, 'Mỗi học sinh nhận 4 thẻ công thức y = kx, viết công thức x theo y và hệ số mới, rồi điền 3 ô trống của bảng giá trị. Bạn cùng bàn kiểm tra bằng phép chia y/x.', '4 thẻ công thức, bảng giá trị', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TLTH-03', 'Chợ quê: bài toán mua bán', array['E-TLTH-04', 'E-TLN-03']::text[], array['loi']::text[], 'nhom-dong-chat', 3, 10, 12, 'Nhóm đóng vai người mua – người bán với giá cho sẵn, giải 4 tình huống (mua nhiều hơn, đổi loại hàng rẻ hơn với cùng số tiền…). Mỗi tình huống ghi rõ "thuận" hay "nghịch" và lập bảng hai hàng trước khi tính.', 'Bảng giá, 4 thẻ tình huống', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TLN-01', 'Ngày công', array['E-TLN-02', 'E-TLN-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Dùng mô hình "ngày công": nhóm tính tổng ngày công của một công việc (4 người × 6 ngày = 24), rồi suy ra số ngày khi đổi số người. Sau đó tự đặt một bài toán vận tốc – thời gian tương tự.', 'Phiếu mô hình ngày công', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C6-MR', 'Công thức pha chế của lớp', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ thiết kế công thức pha nước chanh cho 5 người, sau đó tính lượng nguyên liệu cho cả lớp và cho chuyến dã ngoại; nêu đại lượng nào tỉ lệ thuận, đại lượng nào tỉ lệ nghịch (số người – thời gian pha).', 'Phiếu kế hoạch, giấy A3', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BTDS-01', 'Dịch lời thành biểu thức', array['E-BTDS-01', 'E-BTDS-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 7, 10, 'Nhóm ghép 8 thẻ lời văn với 8 thẻ biểu thức (có 3 thẻ "bẫy" thiếu ngoặc). Sau đó mỗi bạn đọc ngược một biểu thức thành lời để kiểm tra.', '16 thẻ lời văn – biểu thức', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-GTBT-01', 'Thay số có ngoặc', array['E-GTBT-01', 'E-GTBT-02']::text[], array['loi']::text[], 'ca-nhan', 2, 6, 8, 'Học sinh tính giá trị 5 biểu thức tại giá trị âm, bắt buộc viết bước "thay số trong ngoặc" và đánh số thứ tự phép tính. Bạn cùng bàn soát bằng máy tính cầm tay.', 'Phiếu 5 biểu thức, máy tính cầm tay', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DTH-01', 'Thẻ đại số: cộng giữ mũ, nhân cộng mũ', array['E-DTH-01', 'E-DTH-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Dùng thẻ hình (thẻ x, thẻ x², thẻ x³): cộng 2x² + 3x² bằng cách xếp thẻ cùng loại; nhân x² · x³ bằng cách đếm số thừa số x. Nhóm tự rút ra hai quy tắc và ghi lên bảng nhóm.', 'Bộ thẻ đại số, bảng nhóm', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DAT-01', 'Thu gọn – sắp xếp bằng màu', array['E-DAT-01', 'E-DAT-02', 'E-BAC-01', 'E-BAC-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm tô cùng màu các hạng tử cùng bậc (kèm dấu), thu gọn, sắp xếp giảm dần, rồi điền bảng: bậc – hệ số cao nhất – hệ số tự do cho 4 đa thức.', '4 đa thức in sẵn, bút màu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-NGH-01', 'Thám tử nghiệm', array['E-NGH-01', 'E-NGH-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 7, 10, 'Mỗi nhóm nhận 5 đa thức và 6 "nghi phạm" số. Nhóm thay từng số vào, ghi P(a), khoanh số làm P(a) = 0. Có một đa thức không bắt được nghiệm nào — nhóm giải thích vì sao.', 'Phiếu 5 đa thức – 6 số', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CONG-01', 'Đặt cột có ô trống', array['E-CONG-01', 'E-TRU-01']::text[], array['loi']::text[], 'ca-nhan', 2, 8, 10, 'Học sinh cộng, trừ 4 cặp đa thức trên lưới kẻ sẵn cột x³ – x² – x – số; hạng tử khuyết ghi 0. Với phép trừ, viết thêm một dòng "đổi dấu" trước khi cộng.', 'Lưới cột in sẵn', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-NHAN-01', 'Bảng nhân diện tích', array['E-NHAN-01', 'E-NHAN-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm nhân (x + 2)(x + 3) bằng cách vẽ hình chữ nhật chia ô: mỗi ô là một tích riêng. Sau đó làm (2x − 1)(x + 3) và (x + 1)(x² − x + 1) bằng bảng ô, đếm đủ số tích riêng.', 'Giấy kẻ ô, phiếu bảng nhân', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CHIA-01', 'Bốn bước chia cột', array['E-CHIA-01', 'E-CHIA-02', 'E-CHIA-03']::text[], array['loi']::text[], 'nhom-dong-chat', 3, 10, 15, 'Nhóm thực hiện 3 phép chia theo thẻ bốn bước "chia – nhân – trừ – hạ", mỗi bạn đảm nhận một bước rồi xoay vòng. Bước cuối: so bậc dư với bậc chia để quyết định dừng; viết lại A = B · Q + R.', 'Thẻ bốn bước, 3 phép chia', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C7-MR', 'Đa thức của hình', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ thiết kế một hộp giấy từ tấm bìa x × x cm (cắt bốn góc), lập đa thức biểu thị diện tích, thể tích, rồi tính giá trị với x = 20 và so sánh với hộp thật.', 'Tấm bìa, kéo, thước', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BC-01', 'Ba ngăn biến cố', array['E-BC-01', 'E-BC-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 7, 10, 'Nhóm nhận 12 thẻ biến cố (gieo xúc xắc, rút thẻ, thời tiết…), xếp vào ba ngăn Chắc chắn – Không thể – Ngẫu nhiên. Với mỗi thẻ "ngẫu nhiên", nhóm liệt kê các kết quả làm biến cố xảy ra.', '12 thẻ biến cố, bảng ba ngăn', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-XS-01', 'Thước xác suất 0 – 1', array['E-XS-01', 'E-XS-02']::text[], array['loi']::text[], 'ca-lop', 1, 6, 8, 'Giáo viên dán thước dài từ 0 đến 1 trên bảng. Học sinh lần lượt dán thẻ biến cố vào vị trí phù hợp (0, gần 0, 1/2, gần 1, 1) và giải thích bằng số kết quả thuận lợi.', 'Thước giấy 0 – 1, thẻ biến cố', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-XS-02', 'Gieo xu – ghi bảng', array['E-XS-04']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Mỗi nhóm gieo đồng xu 20 lần, ghi kết quả. Trước lần gieo sau một chuỗi 3 lần ngửa, cả nhóm dự đoán; so sánh dự đoán với kết quả thật và với xác suất 1/2.', 'Đồng xu, bảng ghi 20 lần', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-XS-03', 'Đếm theo từng viên, không theo từng loại', array['E-XS-03', 'E-BC-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm dùng túi bi thật (1 đỏ, 3 xanh) và vòng quay chia ô không đều màu. Nhóm ghi từng kết quả đồng khả năng (đánh số viên bi, đánh số ô) trước khi tính xác suất, rồi đối chiếu với cách "đếm theo loại".', 'Túi bi, vòng quay giấy', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C8-MR', 'Thiết kế trò chơi công bằng', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ thiết kế một vòng quay hoặc hộp thẻ cho trò chơi hai người sao cho công bằng (xác suất thắng bằng nhau), giải thích bằng các biến cố đồng khả năng và cho nhóm khác kiểm tra.', 'Bìa, bút màu, thẻ trắng', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-GCD-01', 'Tô màu cặp góc – cạnh đối diện', array['E-GCD-01', 'E-GCD-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 7, 10, 'Nhóm tô cùng màu mỗi góc và cạnh đối diện của nó trên 4 tam giác in sẵn, đo rồi sắp xếp cạnh, góc theo thứ tự. Nhóm tự rút ra quy luật "cạnh lớn – góc lớn".', '4 tam giác in sẵn, thước đo góc, bút màu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DVX-01', 'Đường ngắn nhất ra bờ sông', array['E-DVX-01', 'E-DVX-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 7, 10, 'Trên giấy có đường thẳng d (bờ sông) và điểm A. Nhóm vẽ 5 đoạn từ A đến d, đo độ dài, đánh dấu đoạn ngắn nhất và kiểm tra bằng ê ke rằng nó vuông góc với d.', 'Giấy A4, thước, ê ke', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BDT-01', 'Que tính tam giác', array['E-BDT-01', 'E-BDT-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Nhóm dùng các que dài 2, 3, 4, 5, 6, 7 cm thử ghép tam giác theo 6 bộ ba, ghi bộ nào ghép được, bộ nào không. Đối chiếu với phép so sánh "hai cạnh nhỏ cộng lại với cạnh lớn nhất".', 'Que tính hoặc ống hút cắt sẵn', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TTU-01', 'Gấp giấy tìm trung điểm – trọng tâm', array['E-TTU-01', 'E-TTU-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Học sinh cắt tam giác giấy, gấp để tìm trung điểm ba cạnh, vẽ ba trung tuyến, đánh dấu G. Đo AG và AM để kiểm tra tỉ lệ 2/3, rồi thử đặt tam giác thăng bằng trên đầu bút tại G.', 'Giấy bìa, kéo, thước', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PGT-01', 'Phân giác hay trung tuyến?', array['E-PGT-01', 'E-TTU-01']::text[], array['loi']::text[], 'ca-nhan', 2, 6, 8, 'Trên tam giác không cân, học sinh vẽ cả trung tuyến AM và phân giác AD bằng hai màu, quan sát M và D khác nhau. Sau đó làm lại với tam giác cân tại A để thấy hai đường trùng nhau.', 'Phiếu hai tam giác, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DQ-01', 'Bốn điểm đặc biệt', array['E-PGT-02', 'E-TTRT-01', 'E-DCAO-01', 'E-DCAO-02']::text[], array['loi']::text[], 'nhom-dong-chat', 3, 12, 15, 'Mỗi nhóm nhận một tam giác (nhọn, vuông hoặc tù), dựng ba đường cùng loại theo thẻ được giao (trung trực, phân giác, cao), đánh dấu giao điểm và đo để kiểm tra tính chất cách đều. Các nhóm ghép kết quả thành bảng so sánh vị trí bốn điểm theo loại tam giác.', 'Tam giác in sẵn ba loại, compa, ê ke', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C9-MR', 'Chọn vị trí cho công trình chung', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ nhận bản đồ ba khu dân cư và ba con đường. Nhóm chọn vị trí đặt giếng (cách đều ba khu), trạm quan sát (cách đều ba con đường) và giải thích bằng tính chất các đường đồng quy.', 'Bản đồ in A3, compa, thước', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HHCN-01', 'Khung que và hộp giấy', array['E-HHCN-01', 'E-HHCN-02', 'E-LPH-01']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 12, 'Nhóm dùng que tính và đất nặn dựng khung hình hộp chữ nhật và hình lập phương, đếm và ghi số mặt, cạnh, đỉnh; tô màu các cạnh bằng nhau; dùng sợi chỉ căng một đường chéo của hình hộp và một đường chéo của mặt để so sánh.', 'Que tính, đất nặn, chỉ màu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-SXQ-01', 'Bóc hộp sữa', array['E-SXQ-01', 'E-THT-01']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Mỗi nhóm cắt mở một vỏ hộp sữa giấy, đo các kích thước, tính riêng diện tích bốn mặt bên và hai đáy, so sánh với công thức Sxq = 2(a + b)c. Sau đó tính thể tích và đối chiếu với dung tích in trên hộp.', 'Vỏ hộp sữa giấy, thước, kéo', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DVI-01', 'Một lít là bao nhiêu?', array['E-DVI-01']::text[], array['loi']::text[], 'ca-lop', 1, 5, 8, 'Giáo viên đổ 1 lít nước vào hộp lập phương cạnh 1 dm cho học sinh quan sát. Cả lớp lập chuỗi đổi đơn vị m³ – dm³ – cm³ – lít trên bảng và làm nhanh 5 câu đổi đơn vị.', 'Hộp lập phương 1 dm³, chai 1 lít', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-LPH-01', 'Khối lập phương nhỏ', array['E-LPH-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 7, 10, 'Nhóm ghép các khối lập phương nhỏ thành khối lớn cạnh 2, 3 rồi 4 đơn vị, đếm số khối và số mặt vuông lộ ra ở bốn mặt bên. Nhóm điền bảng cạnh – Sxq – V và tìm quy luật 4a², a³.', 'Bộ khối lập phương nhỏ', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-LTR-01', 'Gấp lăng trụ từ hình khai triển', array['E-LTR-01', 'E-LTR-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Nhóm nhận 4 hình khai triển (2 đúng, 2 sai), dự đoán hình nào gấp được, cắt và gấp thử. Với hình gấp được, nhóm chỉ ra hai đáy, các mặt bên và đo chiều cao.', '4 hình khai triển in trên bìa, kéo, băng dính', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-SXQL-01', 'Băng giấy quấn quanh lăng trụ', array['E-SXQL-01', 'E-VLT-01']::text[], array['loi']::text[], 'nhom-dong-chat', 3, 10, 12, 'Nhóm quấn một băng giấy kín quanh các mặt bên của lăng trụ giấy, mở ra thấy một hình chữ nhật có chiều dài bằng chu vi đáy và chiều rộng bằng chiều cao. Sau đó tính thể tích bằng cách đếm số lớp "đáy" xếp chồng.', 'Lăng trụ giấy, băng giấy, thước', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C10-MR', 'Thiết kế hộp đựng quà', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ thiết kế một hộp quà dạng lăng trụ đứng (tam giác hoặc tứ giác) có thể tích cho trước, vẽ hình khai triển, tính diện tích bìa cần dùng và gấp thử.', 'Bìa A3, thước, kéo, băng dính', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng')
on conflict (activity_id) do nothing;

-- ------------------------------------------------ KIỂM TRA SAU KHI CHẠY
select split_part(ku_id, '-', 1) as chuong, count(*) as so_cau, count(hinh) as co_hinh
from questions where split_part(ku_id, '-', 1) in ('C6','C7','C8','C9','C10') group by 1 order by length(split_part(ku_id, '-', 1)), 1;
